class ConvBNReLU(nn.Module):

    def __init__(self, in_channels, out_channels, kernel_size=3, stride=1, groups=1, act=True):
        super().__init__()
        padding = (kernel_size - 1) // 2 if isinstance(kernel_size, int) else tuple(((k - 1) // 2 for k in kernel_size))
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size, stride=stride, padding=padding, groups=groups, bias=False)
        self.bn = nn.BatchNorm2d(out_channels)
        self.use_act = act
        self.act = nn.Hardswish(inplace=True)

    def forward(self, feats):
        feats = self.conv(feats)
        feats = self.bn(feats)
        if self.use_act:
            feats = self.act(feats)
        return feats

class InvertedResidual(nn.Module):

    def __init__(self, inp, oup, stride, expand_ratio, norm_layer=None):
        super().__init__()
        self.stride = stride
        if norm_layer is None:
            norm_layer = nn.BatchNorm2d
        hidden_dim = int(round(inp * expand_ratio))
        self.use_residual = self.stride == 1 and inp == oup
        layers = []
        if expand_ratio != 1:
            layers.append(ConvBNReLU(inp, hidden_dim, kernel_size=1))
        layers.append(ConvBNReLU(hidden_dim, hidden_dim, kernel_size=5, stride=stride, groups=hidden_dim))
        layers.append(nn.Conv2d(hidden_dim, oup, 1, 1, 0, bias=False))
        layers.append(norm_layer(oup))
        self.conv = nn.Sequential(*layers)

    def forward(self, feats):
        if self.use_residual:
            return feats + self.conv(feats)
        return self.conv(feats)

def _make_divisible(v, divisor=8, min_value=None):
    if min_value is None:
        min_value = divisor
    new_v = max(min_value, int(v + divisor / 2) // divisor * divisor)
    if new_v < 0.9 * v:
        new_v += divisor
    return new_v

class ResStage(nn.Module):

    def __init__(self, t, c, n, stride, se, in_ch, width_mult=1.0):
        super().__init__()
        blocks = []
        out_c = _make_divisible(c * width_mult, 8)
        for i in range(n):
            blocks.append(InvertedResidual(in_ch, out_c, stride if i == 0 else 1, t))
            in_ch = out_c
        self.blocks = nn.Sequential(*blocks)
        self.out_channels = in_ch

    def forward(self, x):
        return self.blocks(x)

class Backbone(nn.Module):

    def __init__(self, settings, in_chans=3, num_classes=10, drop_rate=0.0, width_mult=1.0, norm_layer=None, **kwargs):
        super().__init__()
        if norm_layer is None:
            norm_layer = partial(nn.BatchNorm2d, eps=0.001)
        self.num_classes = num_classes
        self.stem = nn.Sequential(OrderedDict([('conv', nn.Conv2d(in_chans, 16, kernel_size=3, stride=2, padding=1, bias=False)), ('bn', norm_layer(16)), ('act', nn.Hardswish(inplace=True))]))
        in_ch = 16
        stages = []
        for idx, (t, c, n, stride, se) in enumerate(settings):
            stage = ResStage(t, c, n, stride, se, in_ch)
            stages.append(stage)
            in_ch = stage.out_channels
        self.stages = nn.ModuleList(stages)
        self.global_pool = nn.AdaptiveAvgPool2d(1)
        self.classifier = nn.Sequential(OrderedDict([('flatten', nn.Flatten(1)), ('drop', nn.Dropout(p=drop_rate)), ('fc', nn.Linear(in_ch, num_classes))]))

    def forward(self, feats):
        torch._assert(feats.dim() == 4, f'expected a 4D input, got {feats.dim()}D')
        feats = self.stem(feats)
        for stage in self.stages:
            feats = stage(feats)
        feats = self.global_pool(feats)
        return self.classifier(feats)

def _backbone(variant, weights=None, progress=True, **kwargs):
    cfgs = {'small': [(1, 16, 2, 1, False), (3, 24, 2, 2, False), (6, 32, 1, 2, True), (6, 40, 3, 2, True), (6, 48, 2, 2, False)], 'base': [(1, 16, 3, 1, False), (3, 24, 3, 2, False), (6, 32, 2, 2, True), (6, 40, 4, 2, True), (6, 48, 3, 2, False)]}
    model = Backbone(cfgs[variant], **kwargs)
    if weights is not None:
        model.load_state_dict(weights.get_state_dict(progress=progress))
    return model

def build_model(weights=None, progress=True, **kwargs):
    return _backbone('base', weights, progress, **kwargs)
