def make_divisible(v, divisor=8, min_value=None):
    if min_value is None:
        min_value = divisor
    new_v = max(min_value, int(v + divisor / 2) // divisor * divisor)
    if new_v < 0.9 * v:
        new_v += divisor
    return new_v

class ConvNet(nn.Module):

    def __init__(self, stem_stages, main_stages, in_chans=3, num_classes=1000, drop_rate=0.0, width_mult=1.0, norm_layer=None, **kwargs):
        super().__init__()
        if norm_layer is None:
            norm_layer = partial(nn.BatchNorm2d, eps=0.001)
        self.num_classes = num_classes
        self.stem = ConvBN(in_chans, 8, kernel_size=3, stride=2, padding=1)
