import torch
from torch import nn
from torch.nn import functional as F

def make_layers(cfg, batch_norm=False):
    layers = []
    in_channels = 3
    for v in cfg:
        if v == 'M':
            layers += [nn.MaxPool2d(kernel_size=2, stride=2)]
        else:
            conv2d = nn.Conv2d(in_channels, v, kernel_size=3, padding=1)
            if batch_norm:
                layers += [conv2d, nn.BatchNorm2d(v), nn.ReLU6(inplace=True)]
            else:
                layers += [conv2d, nn.ReLU6(inplace=True)]
            in_channels = v
    return nn.Sequential(*layers)

class ConvClassifier(nn.Module):

    def __init__(self, features, num_classes=10, init_weights=True, dropout=0.5):
        super().__init__()
        self.features = features
        self.avgpool = nn.AdaptiveAvgPool2d((1, 1))
        self.classifier = nn.Sequential(nn.Linear(32 * 1 * 1, 32), nn.ReLU(True), nn.Dropout(p=dropout), nn.Linear(32, 32), nn.ReLU(True), nn.Dropout(p=dropout), nn.Linear(32, num_classes))

    def forward(self, feats):
        feats = self.features(feats)
        feats = self.avgpool(feats)
        feats = torch.flatten(feats, 1)
        feats = self.classifier(feats)
        return feats
