from typing import Callable, List, Optional
import torch
import torch.nn as nn
import torch.nn.functional as F
from torch import Tensor

def build_layers(cfg, batch_norm=False):
    layers = []
    in_channels = 3
    for v in cfg:
        if v == 'M':
            layers += [nn.MaxPool2d(kernel_size=2, stride=2)]
        else:
            conv2d = nn.Conv2d(in_channels, v, kernel_size=3, padding=1)
            if batch_norm:
                layers += [conv2d, nn.BatchNorm2d(v), nn.ReLU6(inplace=True)]
            else:
                layers += [conv2d, nn.ReLU6(inplace=True)]
            in_channels = v
    return nn.Sequential(*layers)

class ConvClassifier(nn.Module):

    def __init__(self, features, num_classes=10, init_weights=True, dropout=0.5):
        super().__init__()
        self.features = features
        self.avgpool = nn.AdaptiveAvgPool2d((2, 2))
        self.classifier = nn.Sequential(nn.Linear(32 * 2 * 2, 32), nn.ReLU(True), nn.Dropout(p=dropout), nn.Linear(32, 32), nn.ReLU(True), nn.Dropout(p=dropout), nn.Linear(32, num_classes))

    def forward(self, z):
        z = self.features(z)
        z = self.avgpool(z)
        z = torch.flatten(z, 1)
        z = self.classifier(z)
        return z
cfgs = {'A': [8, 'M', 16, 'M', 32, 32, 'M'], 'B': [8, 'M', 16, 'M', 32, 32, 'M']}

def _convclassifier(cfg, batch_norm, **kwargs):
    return ConvClassifier(build_layers(cfgs[cfg], batch_norm=batch_norm), **kwargs)

def convclassifier_a(**kwargs):
    return _convclassifier('B', False, **kwargs)
