    state_dict = state_dict.get('model', state_dict)
    for k in ('beit3.text_embed.weight', 'beit3.vision_embed.mask_token'):
        state_dict.pop(k, None)
    rules = [('beit3\\.', ''), ('vision_embed\\.cls_token', 'cls_token'), ('vision_embed\\.', 'patch_embed.'), ('embed_positions\\.', 'pos_embed.'), ('encoder\\.', ''), ('layers\\.', 'blocks.'), ('ffn_layernorm\\.', 'norm.'), ('ffn\\.', 'mlp.'), ('self_attn_layer_norm\\.', 'norm1.'), ('self_attn\\.', 'attn.'), ('final_layer_norm\\.', 'norm2.'), ('inner_attn_ln', 'norm'), ('out_proj', 'proj'), ('\\.A\\.', '.')]
    tmp = {}
    for k, v in state_dict.items():
        if '.B.' in k:
            continue
        for old, new in rules:
            k = re.sub(old, new, k)
        if k == 'pos_embed.weight':
            tmp['pos_embed'] = v[2:].unsqueeze(0)
        else:
            tmp[k] = v
    out, buf = ({}, {})
    pat = re.compile('blocks\\.(\\d+)\\.attn\\.(q|k|v)_proj\\.(weight|bias)$')
    for k, v in tmp.items():
        m = pat.fullmatch(k)
        if not m:
            out[k] = v
            continue
        blk, which, kind = m.groups()
        stash = buf.setdefault((blk, kind), {})
        stash[which] = v
        if len(stash) == 3:
            out[f'blocks.{blk}.attn.qkv.{kind}'] = torch.cat([stash['q'], stash['k'], stash['v']], dim=0)
    return out

def _convert_radio(state_dict, model=None, interpolation='bilinear', antialias=False, align_corners=None):
    out_dict = {}
    prefix = 'radio_model.model.'
    for k, v in state_dict.items():
        if not k.startswith(prefix):
            continue
        k = k[len(prefix):]
        if k == 'patch_generator.embedder.weight':
            p = int(math.sqrt(v.shape[1] // 3))
            out_dict['patch_embed.proj.weight'] = v.reshape(v.shape[0], 3, p, p)
            out_dict['patch_embed.proj.bias'] = v.new_zeros(v.shape[0])
        elif k == 'patch_generator.pos_embed':
            out_dict['pos_embed'] = v
        elif k == 'patch_generator.cls_token.token':
            out_dict['cls_token'] = v[None, :1]
            out_dict['reg_token'] = v[None, 1:]
        elif k.startswith('blocks.'):
            out_dict[k.replace('.grandma', '.gamma')] = v
    if model is not None and model.pos_embed is not None and ('pos_embed' in out_dict):
        grid_size = model.patch_embed.grid_size
        max_size = max(grid_size)
        pos_embed = resample_abs_pos_embed(out_dict['pos_embed'], new_size=(max_size, max_size), num_prefix_tokens=0, interpolation=interpolation, antialias=antialias, align_corners=align_corners)
        pos_embed = pos_embed.reshape(1, max_size, max_size, -1)[:, :grid_size[0], :grid_size[1]]
        out_dict['pos_embed'] = pos_embed.reshape(1, grid_size[0] * grid_size[1], -1)
    return out_dict

def checkpoint_filter_fn(state_dict, model, adapt_layer_scale=False, interpolation='bicubic', antialias=True, align_corners=None):
    import re
    out_dict = {}
    state_dict = state_dict.get('model', state_dict)
    state_dict = state_dict.get('state_dict', state_dict)
    prefix = ''
    resample_pos_embed = True
    if 'visual.class_embedding' in state_dict:
        state_dict = _convert_openai_clip(state_dict, model)
    elif 'module.visual.class_embedding' in state_dict:
        state_dict = _convert_openai_clip(state_dict, model, prefix='module.visual.')
    elif 'mask_token' in state_dict:
        state_dict = _convert_dinov2(state_dict, model)
    elif 'vision_encoder.mask_token' in state_dict:
        ve_prefix = 'vision_encoder.'
        state_dict = {k[len(ve_prefix):]: v for k, v in state_dict.items() if k.startswith(ve_prefix)}
        state_dict = _convert_dinov2(state_dict, model)
    elif any(('beit3.' in k for k in state_dict.keys())):
        state_dict = _convert_beit3(state_dict, model)
    elif 'encoder' in state_dict:
        state_dict = state_dict['encoder']
        prefix = 'module.'
    elif 'visual.trunk.pos_embed' in state_dict or 'visual.trunk.blocks.0.norm1.weight' in state_dict:
        prefix = 'visual.trunk.'
        if 'visual.head.proj.weight' in state_dict and isinstance(model.head, nn.Linear):
            out_dict['head.weight'] = state_dict['visual.head.proj.weight']
            out_dict['head.bias'] = torch.zeros(state_dict['visual.head.proj.weight'].shape[0])
    elif 'module.visual.trunk.pos_embed' in state_dict:
        prefix = 'module.visual.trunk.'
    elif 'preprocessor.patchifier.proj.weight' in state_dict:
        state_dict = _convert_aimv2(state_dict, model)
    elif 'radio_model.model.patch_generator.embedder.weight' in state_dict:
        state_dict = _convert_radio(state_dict, model, interpolation=interpolation, antialias=antialias, align_corners=align_corners)
        resample_pos_embed = False
    if prefix:
        state_dict = {k[len(prefix):]: v for k, v in state_dict.items() if k.startswith(prefix)}
    for k, v in state_dict.items():
        if 'patch_embed.proj.weight' in k:
            O, I, H, W = model.patch_embed.proj.weight.shape
            if len(v.shape) < 4:
                O, I, H, W = model.patch_embed.proj.weight.shape
                v = v.reshape(O, -1, H, W)
            if v.shape[-1] != W or v.shape[-2] != H:
                v = resample_patch_embed(v, (H, W), interpolation=interpolation, antialias=antialias, verbose=True)
        elif k == 'pos_embed' and model.pos_embed is not None and resample_pos_embed:
            num_prefix_tokens = 0 if getattr(model, 'no_embed_class', False) else getattr(model, 'num_prefix_tokens', 1)
            old_size = get_pretrained_grid_size(model, state_dict.get('patch_embed.proj.weight'), v.shape[1] - num_prefix_tokens)
            if v.shape[1] != model.pos_embed.shape[1] or (old_size is not None and old_size != model.patch_embed.grid_size):
                v = resample_abs_pos_embed(v, new_size=model.patch_embed.grid_size, old_size=old_size, num_prefix_tokens=num_prefix_tokens, interpolation=interpolation, antialias=antialias, verbose=True, align_corners=align_corners)
        elif adapt_layer_scale and 'gamma_' in k:
            k = re.sub('gamma_([0-9])', 'ls\\1.gamma', k)
        elif 'pre_logits' in k:
            continue
        out_dict[k] = v
    return out_dict
