class Stem(nn.Module):

    def __init__(self, in_chs, out_chs, act_layer='gelu', norm_layer='layernorm2d', norm_eps=1e-06, bias=True, device=None, dtype=None):
        dd = {'device': device, 'dtype': dtype}
        super().__init__()
        norm_act_layer = partial(get_norm_act_layer(norm_layer, act_layer), eps=norm_eps)
        self.out_chs = out_chs
        self.conv1 = create_conv2d(in_chs, out_chs, 3, stride=2, bias=bias, **dd)
        self.norm1 = norm_act_layer(out_chs, **dd)
        self.conv2 = create_conv2d(out_chs, out_chs, 3, stride=1, bias=bias, **dd)

    def forward(self, x):
        x = self.conv1(x)
        x = self.norm1(x)
        x = self.conv2(x)
        return x

class Downsample2d(nn.Module):

    def __init__(self, dim, dim_out, pool_type='avg2', bias=True, device=None, dtype=None):
        dd = {'device': device, 'dtype': dtype}
        super().__init__()
        self.pool = nn.AvgPool2d(kernel_size=3, stride=2, padding=1, count_include_pad=False)
        if dim != dim_out:
            self.expand = nn.Conv2d(dim, dim_out, 1, bias=bias, **dd)
        else:
            self.expand = nn.Identity()

    def forward(self, x):
        x = self.pool(x)
        x = self.expand(x)
        return x

class StridedConv(nn.Module):

    def __init__(self, kernel_size=3, stride=2, padding=1, in_chans=3, embed_dim=768, device=None, dtype=None):
        dd = {'device': device, 'dtype': dtype}
        super().__init__()
        norm_layer = partial(get_norm_layer('layernorm2d'), eps=1e-06)
        self.proj = nn.Conv2d(in_chans, embed_dim, kernel_size=kernel_size, stride=stride, padding=padding, **dd)
        self.norm = norm_layer(in_chans, **dd)

    def forward(self, x):
        x = self.norm(x)
        x = self.proj(x)
        return x

class MbConvLNBlock(nn.Module):

    def __init__(self, in_chs, out_chs, stride=1, drop_path=0.0, kernel_size=3, norm_layer='layernorm2d', norm_eps=1e-06, act_layer='gelu', expand_ratio=4.0, device=None, dtype=None):
        dd = {'device': device, 'dtype': dtype}
        super().__init__()
        self.stride, self.in_chs, self.out_chs = (stride, in_chs, out_chs)
        mid_chs = make_divisible(out_chs * expand_ratio)
        prenorm_act_layer = partial(get_norm_act_layer(norm_layer, act_layer), eps=norm_eps)
        if stride == 2:
            self.shortcut = Downsample2d(in_chs, out_chs, pool_type='avg', bias=True, **dd)
        elif in_chs != out_chs:
            self.shortcut = nn.Conv2d(in_chs, out_chs, 1, bias=True, **dd)
        else:
            self.shortcut = nn.Identity()
        self.pre_norm = prenorm_act_layer(in_chs, apply_act=False, **dd)
        self.down = nn.Identity()
        self.conv1_1x1 = create_conv2d(in_chs, mid_chs, 1, stride=1, bias=True, **dd)
        self.act1 = create_act_layer(act_layer, inplace=True)
        self.conv2_kxk = create_conv2d(mid_chs, mid_chs, kernel_size, stride=stride, dilation=1, groups=mid_chs, bias=True, **dd)
        self.act2 = create_act_layer(act_layer, inplace=True)
        self.conv3_1x1 = create_conv2d(mid_chs, out_chs, 1, bias=True, **dd)
        self.drop_path = DropPath(drop_path) if drop_path > 0.0 else nn.Identity()

    def forward(self, x):
        shortcut = self.shortcut(x)
        x = self.pre_norm(x)
        x = self.down(x)
        x = self.conv1_1x1(x)
        x = self.act1(x)
        x = self.conv2_kxk(x)
        x = self.act2(x)
        x = self.conv3_1x1(x)
        x = self.drop_path(x) + shortcut
        return x

class MbConvStages(nn.Module):

    def __init__(self, cfg, img_size=224, in_chans=3, device=None, dtype=None):
        dd = {'device': device, 'dtype': dtype}
        super().__init__()
        self.grad_checkpointing = False
        self.stem = Stem(in_chs=in_chans, out_chs=cfg.stem_width, **dd)
        stages = []
        self.num_stages = len(cfg.embed_dim)
        for s, dim in enumerate(cfg.embed_dim[:2]):
            stage_in_chs = cfg.embed_dim[s - 1] if s > 0 else cfg.stem_width
            blocks = [MbConvLNBlock(in_chs=stage_in_chs if d == 0 else dim, out_chs=dim, stride=2 if d == 0 else 1, **dd) for d in range(cfg.depths[s])]
            stages += [nn.Sequential(*blocks)]
        self.stages = nn.Sequential(*stages)
        self.pool = StridedConv(stride=2, in_chans=cfg.embed_dim[1], embed_dim=cfg.embed_dim[2], **dd)

    def forward(self, x):
        x = self.stem(x)
        if self.grad_checkpointing and (not torch.jit.is_scripting()):
            x = checkpoint_seq(self.stages, x)
        else:
            x = self.stages(x)
        x = self.pool(x)
        return x

class GeGluMlp(nn.Module):

    def __init__(self, in_features, hidden_features, act_layer='gelu', norm_layer=None, bias=True, drop=0.0, device=None, dtype=None):
        dd = {'device': device, 'dtype': dtype}
        super().__init__()
        norm_layer = partial(get_norm_layer(norm_layer or 'layernorm'), eps=1e-06)
        self.norm = norm_layer(in_features, **dd)
        self.w0 = nn.Linear(in_features, hidden_features, bias=bias, **dd)
        self.act = create_act_layer(act_layer)
        self.w1 = nn.Linear(in_features, hidden_features, bias=bias, **dd)
        self.drop1 = nn.Dropout(drop)
        self.w2 = nn.Linear(hidden_features, in_features, bias=bias, **dd)
        self.drop2 = nn.Dropout(drop)

    def forward(self, x):
        x = self.norm(x)
        x = self.act(self.w0(x)) * self.w1(x)
        x = self.drop1(x)
        x = self.w2(x)
        x = self.drop2(x)
        return x

def _create_vitamin(variant, pretrained=False, embed_cfg=None, **kwargs):
    out_indices = kwargs.pop('out_indices', 3)
    assert embed_cfg is not None
    dd = {'device': kwargs.get('device', None), 'dtype': kwargs.get('dtype', None)}
    backbone = MbConvStages(cfg=embed_cfg, in_chans=kwargs.get('in_chans', 3), **dd)
    kwargs['embed_layer'] = partial(HybridEmbed, backbone=backbone, proj=False)
    kwargs.setdefault('patch_size', 1)
    return build_model_with_cfg(VisionTransformer, variant, pretrained, pretrained_filter_fn=checkpoint_filter_fn, feature_cfg=dict(out_indices=out_indices, feature_cls='getter'), **kwargs)

