from ._registry import register_model, generate_default_cfgs

class SequentialList(nn.Sequential):

    def __init__(self, *args):
        super().__init__(*args)

    def forward(self, x):
        for module in self:
            x = module(x)
        return x

class SelectSeq(nn.Module):

    def __init__(self, mode='index', index=0):
        super().__init__()
        self.mode = mode
        self.index = index

    def forward(self, x):
        if self.mode == 'index':
            return x[self.index]
        else:
            return torch.cat(x, dim=1)

def conv_bn(in_chs, out_chs, k=3, stride=1, padding=None, dilation=1, device=None, dtype=None):
    dd = {'device': device, 'dtype': dtype}
    if padding is None:
        padding = (stride - 1 + dilation * (k - 1)) // 2
    return nn.Sequential(nn.Conv2d(in_chs, out_chs, k, stride, padding=padding, dilation=dilation, bias=False, **dd), nn.BatchNorm2d(out_chs, **dd), nn.ReLU(inplace=True))

class SelecSlsBlock(nn.Module):

    def __init__(self, in_chs, skip_chs, mid_chs, out_chs, is_first, stride, dilation=1, device=None, dtype=None):
        dd = {'device': device, 'dtype': dtype}
        super().__init__()
        self.stride = stride
        self.is_first = is_first
        assert stride in [1, 2]
        self.conv1 = conv_bn(in_chs, mid_chs, 3, stride, dilation=dilation, **dd)
        self.conv2 = conv_bn(mid_chs, mid_chs, 1, **dd)
        self.conv3 = conv_bn(mid_chs, mid_chs // 2, 3, **dd)
        self.conv4 = conv_bn(mid_chs // 2, mid_chs, 1, **dd)
        self.conv5 = conv_bn(mid_chs, mid_chs // 2, 3, **dd)
        self.conv6 = conv_bn(2 * mid_chs + (0 if is_first else skip_chs), out_chs, 1, **dd)

    def forward(self, x):
        if not isinstance(x, list):
            x = [x]
        assert len(x) in [1, 2]
        d1 = self.conv1(x[0])
        d2 = self.conv3(self.conv2(d1))
        d3 = self.conv5(self.conv4(d2))
        if self.is_first:
            out = self.conv6(torch.cat([d1, d2, d3], 1))
            return [out, out]
        else:
