    def __init__(self, cfg, num_classes=1000, in_chans=3, drop_rate=0.0, global_pool='avg', device=None, dtype=None):
        self.num_classes = num_classes
        self.in_chans = in_chans
        super().__init__()
        dd = {'device': device, 'dtype': dtype}
        self.stem = conv_bn(in_chans, 32, stride=2, **dd)
        self.features = SequentialList(*[cfg['block'](*block_args, **dd) for block_args in cfg['features']])
        self.from_seq = SelectSeq()
        self.head = nn.Sequential(*[conv_bn(*conv_args, **dd) for conv_args in cfg['head']])
        self.num_features = cfg['num_features']
        self.feature_info = cfg['feature_info']
        self.feature_ends = []
        for f in self.feature_info:
            name, idx = f['module'].split('.')
            if name == 'stem':
                self.feature_ends.append(-1)
            elif name == 'features':
                self.feature_ends.append(int(idx))
            else:
                self.feature_ends.append(len(self.features) + int(idx))
        self.global_pool, self.head_drop, self.fc = create_classifier(self.num_features, self.num_classes, pool_type=global_pool, drop_rate=drop_rate, **dd)
        self.head_hidden_size = self.num_features * self.global_pool.feat_mult()

    def forward_features(self, x):
        x = self.stem(x)
        x = self.features([x])
        x = self.head(self.from_seq(x))
        return x

    def forward_head(self, x, pre_logits=False):
        x = self.global_pool(x)
        x = self.head_drop(x)
        return x if pre_logits else self.fc(x)

    def forward(self, x):
        x = self.forward_features(x)
        x = self.forward_head(x)
        return x

