class AttentionDownsample(nn.Module):

    def __init__(self, in_dim, out_dim, key_dim, num_heads=8, attn_ratio=2.0, stride=2, resolution=14, use_conv=False, use_pool=False, act_layer=nn.SiLU, device=None, dtype=None):
        dd = {'device': device, 'dtype': dtype}
        super().__init__()
        resolution = to_2tuple(resolution)
        self.stride = stride
        self.resolution = resolution
        self.num_heads = num_heads
        self.key_dim = key_dim
        self.key_attn_dim = key_dim * num_heads
        self.val_dim = int(attn_ratio * key_dim)
        self.val_attn_dim = self.val_dim * self.num_heads
        self.scale = key_dim ** (-0.5)
        self.use_conv = use_conv
        if self.use_conv:
            ln_layer = ConvNorm
            sub_layer = partial(nn.AvgPool2d, kernel_size=3 if use_pool else 1, padding=1 if use_pool else 0, count_include_pad=False)
        else:
            ln_layer = LinearNorm
            sub_layer = partial(Downsample, resolution=resolution, use_pool=use_pool, **dd)
        self.kv = ln_layer(in_dim, self.val_attn_dim + self.key_attn_dim, **dd)
        self.q = nn.Sequential(OrderedDict([('down', sub_layer(stride=stride)), ('ln', ln_layer(in_dim, self.key_attn_dim, **dd))]))
        self.proj = nn.Sequential(OrderedDict([('act', act_layer()), ('ln', ln_layer(self.val_attn_dim, out_dim, **dd))]))
        N_k = resolution[0] * resolution[1]
        N_q = -(-resolution[0] // stride) * -(-resolution[1] // stride)
        self.attention_biases = nn.Parameter(torch.empty(num_heads, N_k, **dd))
        self.register_buffer('attention_bias_idxs', torch.empty((N_q, N_k), device=device, dtype=torch.long), persistent=False)
        self.attention_bias_cache = {}
        self.reset_parameters()

    @torch.no_grad()
    def train(self, mode=True):
        super().train(mode)
        if self.attention_bias_cache:
            self.attention_bias_cache = {}

    def _apply(self, fn, *args, **kwargs):
        self.attention_bias_cache = {}
        return super()._apply(fn, *args, **kwargs)

    def reset_parameters(self):
        self._init_buffers()

    def _compute_attention_bias_idxs(self, device=None):
        k_pos = torch.stack(ndgrid(torch.arange(self.resolution[0], device=device, dtype=torch.long), torch.arange(self.resolution[1], device=device, dtype=torch.long))).flatten(1)
        q_pos = torch.stack(ndgrid(torch.arange(0, self.resolution[0], step=self.stride, device=device, dtype=torch.long), torch.arange(0, self.resolution[1], step=self.stride, device=device, dtype=torch.long))).flatten(1)
        rel_pos = (q_pos[..., :, None] - k_pos[..., None, :]).abs()
        rel_pos = rel_pos[0] * self.resolution[1] + rel_pos[1]
        return rel_pos

    def _init_buffers(self):
        self.attention_bias_idxs.copy_(self._compute_attention_bias_idxs(device=self.attention_bias_idxs.device))
        self.attention_bias_cache = {}

    def get_attention_biases(self, device):
        if torch.jit.is_tracing() or self.training:
            return self.attention_biases[:, self.attention_bias_idxs]
        else:
            device_key = str(device)
            if device_key not in self.attention_bias_cache:
                self.attention_bias_cache[device_key] = self.attention_biases[:, self.attention_bias_idxs]
            return self.attention_bias_cache[device_key]

    def forward(self, x):
        if self.use_conv:
            B, C, H, W = x.shape
            HH, WW = ((H - 1) // self.stride + 1, (W - 1) // self.stride + 1)
            k, v = self.kv(x).view(B, self.num_heads, -1, H * W).split([self.key_dim, self.val_dim], dim=2)
            q = self.q(x).view(B, self.num_heads, self.key_dim, -1)
            attn = q.transpose(-2, -1) @ k * self.scale + self.get_attention_biases(x.device)
            attn = attn.softmax(dim=-1)
            x = (v @ attn.transpose(-2, -1)).reshape(B, self.val_attn_dim, HH, WW)
        else:
            B, N, C = x.shape
            k, v = self.kv(x).view(B, N, self.num_heads, -1).split([self.key_dim, self.val_dim], dim=3)
            k = k.permute(0, 2, 3, 1)
            v = v.permute(0, 2, 1, 3)
            q = self.q(x).view(B, -1, self.num_heads, self.key_dim).permute(0, 2, 1, 3)
            attn = q @ k * self.scale + self.get_attention_biases(x.device)
            attn = attn.softmax(dim=-1)
            x = (attn @ v).transpose(1, 2).reshape(B, -1, self.val_attn_dim)
        x = self.proj(x)
        return x
