from typing import Any, Callable, List, Optional
import torch
from torch import Tensor, nn
import torch.nn.functional as F
from torchvision.ops import Conv2dNormActivation
from functools import partial
from torch.utils.checkpoint import checkpoint_sequential

def round_width(width, group_width):
    group_width = min(group_width, width)
    return int(round(width / group_width) * group_width)

class YBlock(nn.Module):

    def __init__(self, in_ch, out_ch, stride, group_width, bottleneck_ratio=1.0, se_ratio=None):
        super().__init__()
        w_b = int(round(out_ch * bottleneck_ratio))
        groups = w_b // group_width
        self.f_a = nn.Sequential(nn.Conv2d(in_ch, w_b, 1, bias=False), nn.BatchNorm2d(w_b), nn.SiLU(inplace=True))
        self.f_b = nn.Sequential(nn.Conv2d(w_b, w_b, 3, stride=stride, padding=1, groups=groups, bias=False), nn.BatchNorm2d(w_b), nn.SiLU(inplace=True))
        self.se = None
        self.f_c = nn.Sequential(nn.Conv2d(w_b, out_ch, 1, bias=False), nn.BatchNorm2d(out_ch))
        self.shortcut = None
        if in_ch != out_ch or stride != 1:
            self.shortcut = nn.Sequential(nn.Conv2d(in_ch, out_ch, 1, stride=stride, bias=False), nn.BatchNorm2d(out_ch))
        self.act = nn.SiLU(inplace=True)

    def forward(self, tensor):
        shortcut = tensor if self.shortcut is None else self.shortcut(tensor)
        tensor = self.f_a(tensor)
        tensor = self.f_b(tensor)
        if self.se is not None:
            tensor = self.se(tensor)
        tensor = self.f_c(tensor)
        return self.act(tensor + shortcut)

def make_conv3(in_planes, out_planes, stride=1, groups=1):
    return nn.Conv2d(in_planes, out_planes, kernel_size=3, stride=stride, padding=1, groups=groups, bias=False)

class SkipBlock(nn.Module):
    expansion = 1

    def __init__(self, inplanes, planes, stride=1, shortcut=None, norm_layer=None):
        super().__init__()
        if norm_layer is None:
            norm_layer = nn.BatchNorm2d
        self.conv1 = make_conv3(inplanes, planes, stride)
        self.bn1 = norm_layer(planes)
        self.conv2 = make_conv3(planes, planes)
        self.bn2 = norm_layer(planes)
        self.relu1 = nn.SiLU(inplace=True)
        self.relu2 = nn.SiLU(inplace=True)
        self.shortcut = shortcut
        self.stride = stride

    def forward(self, tensor):
        residual = tensor
        out = self.conv1(tensor)
        out = self.bn1(out)
        out = self.relu1(out)
        out = self.conv2(out)
        out = self.bn2(out)
        if self.shortcut is not None:
            residual = self.shortcut(tensor)
        out += residual
        out = self.relu2(out)
        return out

def conv1(in_planes, out_planes, stride=1):
    return nn.Conv2d(in_planes, out_planes, kernel_size=1, stride=stride, bias=False)

def downsample_conv(in_chs, out_chs, stride=1, norm_layer=None):
    if norm_layer is None:
        norm_layer = nn.BatchNorm2d
    return nn.Sequential(nn.Conv2d(in_chs, out_chs, kernel_size=1, stride=stride, bias=False), norm_layer(out_chs))

def downsample_avg(in_chs, out_chs, stride=1, norm_layer=None):
    if norm_layer is None:
        norm_layer = nn.BatchNorm2d
    pool = nn.AvgPool2d(2, stride, ceil_mode=True, count_include_pad=False) if stride > 1 else nn.Identity()
    return nn.Sequential(pool, nn.Conv2d(in_chs, out_chs, kernel_size=1, stride=1, bias=False), norm_layer(out_chs))

class Backbone(nn.Module):

    def __init__(self, block, stem_stages, main_stages, in_chans=3, num_classes=1000, drop_rate=0.0, norm_layer=None, down_type='conv', output_stride=32, **kwargs):
        super().__init__()
        assert output_stride in (8, 16, 32)
        if norm_layer is None:
            norm_layer = partial(nn.BatchNorm2d, eps=0.001)
        self.num_classes = num_classes
        self.stem = Conv2dNormActivation(in_chans, 8, kernel_size=3, stride=2)
        in_ch = 8
        stages = []
        for idx, (w, d, g) in enumerate(stem_stages):
            blocks = []
            w = round_width(w, g)
            for i in range(d):
                blocks.append(YBlock(in_ch, w, 2 if i == 0 else 1, g))
                in_ch = w
            stages.append(nn.Sequential(*blocks))
        for idx, (planes, n, stride) in enumerate(main_stages, start=len(stem_stages)):
            blocks = []
            downsample = None
            if stride != 1 or in_ch != planes * block.expansion:
                down_fn = downsample_avg if down_type == 'avg' else downsample_conv
                downsample = down_fn(in_ch, planes * block.expansion, stride, norm_layer)
            blocks.append(block(in_ch, planes, stride, downsample))
            in_ch = planes * block.expansion
            for _ in range(1, n):
                blocks.append(block(in_ch, planes))
            stages.append(nn.Sequential(*blocks))
        self.stages = nn.Sequential(*stages)
        self.grad_checkpointing = False
        self.drop = nn.Identity()
        self.fc = nn.Linear(in_ch, num_classes)

    def forward(self, tensor):
        tensor = self.stem(tensor)
        if self.grad_checkpointing and (not torch.jit.is_scripting()):
            tensor = checkpoint_sequential(self.stages, len(self.stages), tensor)
        else:
            tensor = self.stages(tensor)
        tensor = F.adaptive_avg_pool2d(tensor, 1)
        tensor = torch.flatten(tensor, 1)
        tensor = self.drop(tensor)
        return self.fc(tensor)

def _backbone(variant, weights=None, progress=True, **kwargs):
    cfgs = {'small': ([(24, 2, 8), (40, 1, 8), (48, 3, 8)], [(64, 1, 2)])}
    model = Backbone(SkipBlock, *cfgs[variant], **kwargs)
    if weights is not None:
        model.load_state_dict(weights.get_state_dict(progress=progress))
    return model

def backbone_small(weights=None, progress=True, **kwargs):
    return _backbone('small', weights, progress, **kwargs)
model = backbone_small(num_classes=100)
example_input = torch.randn(1, 3, 64, 64)
