import torch
import torch.nn as nn
import torch.nn.functional as F
from timm.layers import AttentionRope, DropPath, GluMlp, PatchEmbed, RmsNormFp32, RotaryEmbeddingCat, calculate_drop_path_rates, get_device_dtype, trunc_normal_
from ._builder import build_model_with_cfg, resolve_pretrained_cfg
from ._features import feature_take_indices
from ._manipulate import checkpoint
from ._registry import generate_default_cfgs, register_model

class DeepseekVitBlock(nn.Module):

    def __init__(self, dim, num_heads, mlp_ratio=2.75, proj_drop=0.0, attn_drop=0.0, drop_path=0.0, norm_layer=RmsNormFp32, device=None, dtype=None):
        dd = {'device': device, 'dtype': dtype}
        super().__init__()
        self.norm1 = norm_layer(dim, **dd)
        self.attn = AttentionRope(dim, num_heads=num_heads, qkv_bias=True, qkv_fused=True, num_prefix_tokens=0, rotate_half=True, proj_bias=True, attn_drop=attn_drop, proj_drop=proj_drop, **dd)
        self.drop_path1 = DropPath(drop_path) if drop_path > 0.0 else nn.Identity()
        self.norm2 = norm_layer(dim, **dd)
        self.mlp = GluMlp(in_features=dim, hidden_features=int(dim * mlp_ratio) * 2, act_layer=nn.SiLU, gate_last=False, bias=False, drop=proj_drop, **dd)
        self.drop_path2 = DropPath(drop_path) if drop_path > 0.0 else nn.Identity()

    def forward(self, x, rope=None):
        x = x + self.drop_path1(self.attn(self.norm1(x), rope=rope))
        x = x + self.drop_path2(self.mlp(self.norm2(x)))
        return x

class DeepseekVitAligner(nn.Module):

    def __init__(self, dim, downsample_ratio=3, out_features=0, act_layer=nn.GELU, device=None, dtype=None):
        dd = {'device': device, 'dtype': dtype}
        super().__init__()
        assert out_features > 0, 'the DeepSeek aligner projects to the source LLM width, pass out_features'
        assert downsample_ratio > 0
        self.downsample_ratio = downsample_ratio
        self.hidden_size = dim * downsample_ratio ** 2
        self.out_features = out_features
        self.fc1 = nn.Linear(self.hidden_size, out_features, **dd)
        self.act = act_layer()
        self.fc2 = nn.Linear(out_features, out_features, **dd)

    def unshuffle(self, x):
        B, H, W, C = x.shape
        r = self.downsample_ratio
        x = x.permute(0, 3, 1, 2)
        pad_h, pad_w = (-H % r, -W % r)
        x = F.pad(x, (0, pad_w, 0, pad_h))
        h, w = ((H + pad_h) // r, (W + pad_w) // r)
        x = x.reshape(B, C, h, r, w, r).permute(0, 2, 4, 1, 3, 5)
        return x.reshape(B, h * w, C * r * r)

    def forward(self, x, pre_logits=False):
        x = self.act(self.fc1(self.unshuffle(x)))
        return x if pre_logits else self.fc2(x)

class DeepseekVitEncoder(nn.Module):
    output_fmt = 'NHWC'

    def __init__(self, img_size=546, patch_size=14, in_chans=3, out_features=0, global_pool='align', embed_dim=1024, depth=32, num_heads=16, mlp_ratio=2816 / 1024, downsample_ratio=3, rope_temperature=10000.0, norm_eps=1e-06, proj_drop_rate=0.0, attn_drop_rate=0.0, drop_path_rate=0.0, dynamic_img_pad=False, device=None, dtype=None):
        super().__init__()
        dd = {'device': device, 'dtype': dtype}
        assert global_pool in ('', 'avg', 'align'), 'Only avg or align pooling (or none) is supported.'
        assert embed_dim % num_heads == 0
        self.in_chans = in_chans
        self.num_classes = 0
        self.global_pool = global_pool
        self.num_features = self.head_hidden_size = self.embed_dim = embed_dim
        self.out_features = out_features
        self.downsample_ratio = downsample_ratio
        self.num_prefix_tokens = 0
        self.feature_dim = -1
        self.grad_checkpointing = False
        norm_layer = partial(RmsNormFp32, eps=norm_eps)
        head_dim = embed_dim // num_heads
        assert head_dim % 4 == 0, 'Axial 2D RoPE requires a head dimension divisible by four.'
        self.patch_embed = PatchEmbed(img_size=img_size, patch_size=patch_size, in_chans=in_chans, embed_dim=embed_dim, bias=True, strict_img_size=False, dynamic_img_pad=dynamic_img_pad, output_fmt='NHWC', **dd)
        r = self.patch_embed.feat_ratio()
        self.rope = RotaryEmbeddingCat(dim=head_dim, temperature=rope_temperature, in_pixels=False, feat_shape=None, rotate_half=True, **dd)
        dpr = calculate_drop_path_rates(drop_path_rate, depth)
        self.blocks = nn.ModuleList([DeepseekVitBlock(dim=embed_dim, num_heads=num_heads, mlp_ratio=mlp_ratio, proj_drop=proj_drop_rate, attn_drop=attn_drop_rate, drop_path=dpr[i], norm_layer=norm_layer, **dd) for i in range(depth)])
        self.feature_info = [dict(module=f'blocks.{i}', num_chs=embed_dim, reduction=r) for i in range(depth)]
        self.norm = norm_layer(embed_dim, **dd)
        self.aligner = DeepseekVitAligner(embed_dim, downsample_ratio=downsample_ratio, out_features=out_features, **dd) if global_pool == 'align' else None
        if self.aligner is not None:
            self.head_hidden_size = self.aligner.out_features

    def _pos_embed(self, x):
        B, H, W, C = x.shape
        return (x.reshape(B, H * W, C), self.rope.get_embed(shape=(H, W)))

    def forward_features(self, x):
        x = self.patch_embed(x)
        B, H, W, _ = x.shape
        x, rope = self._pos_embed(x)
        for blk in self.blocks:
            if self.grad_checkpointing and (not torch.jit.is_scripting()):
                x = checkpoint(blk, x, rope=rope)
            else:
                x = blk(x, rope=rope)
        return self.norm(x).reshape(B, H, W, -1)

    def forward(self, x):
        x = self.forward_features(x)
        if self.aligner is not None:
            return self.aligner(x)
        if self.global_pool == 'avg':
            x = x.mean(dim=(1, 2))
        return x

def checkpoint_filter_fn_encoder(state_dict, model):
    from_source = any((k.startswith('vision.') for k in state_dict))
    out_dict = {}
    for k, v in state_dict.items():
        if k.startswith('encoder.'):
            k = k.replace('encoder.', '', 1)
        elif from_source:
            if k.startswith('vision.'):
                k = k.replace('vision.', '', 1)
            elif not k.startswith('aligner.'):
                continue
        elif not k.startswith(('patch_embed.', 'blocks.', 'norm.', 'aligner.')):
            continue
        if k.startswith('aligner.'):
            if model.aligner is None:
                continue
            k = k.replace('aligner.w1.', 'aligner.fc1.', 1).replace('aligner.w2.', 'aligner.fc2.', 1)
            out_dict[k] = v
            continue
        if k == 'patch_embed.proj.weight' and v.ndim == 2:
            v = v.reshape(v.shape[0], -1, *model.patch_embed.patch_size)
        k = k.replace('.attn.wqkv.', '.attn.qkv.').replace('.attn.wo.', '.attn.proj.')
        k = k.replace('.mlp.w1.', '.mlp.fc1.').replace('.mlp.w2.', '.mlp.fc2.')
        out_dict[k] = v
    return out_dict

def _resolve_deepseek_out_features(variant, tag):
    source_arch = variant.rsplit('_', 1)[0] if variant.endswith(('_enc', '_align')) else variant
    source_name = f'{source_arch}.{tag}'
    if source_name not in _SOURCE_CFGS:
        raise ValueError('Specify out_features for a DeepSeek aligner with a custom pretrained configuration.')
    return _SOURCE_CFGS[source_name]['out_features']

def _create_deepseek_vit_encoder(variant, pretrained=False, **kwargs):
    pretrained_cfg = resolve_pretrained_cfg(variant, pretrained_cfg=kwargs.pop('pretrained_cfg', None), pretrained_cfg_overlay=kwargs.pop('pretrained_cfg_overlay', None))
    if 'out_features' not in kwargs:
        kwargs['out_features'] = _resolve_deepseek_out_features(variant, pretrained_cfg.tag)
    out_indices = kwargs.pop('out_indices', 3)
    return build_model_with_cfg(DeepseekVitEncoder, variant, pretrained, pretrained_cfg=pretrained_cfg, pretrained_filter_fn=checkpoint_filter_fn_encoder, feature_cfg=dict(out_indices=out_indices, feature_cls='getter'), kwargs_filter=('num_classes', 'drop_rate'), **kwargs)

@register_model
def deepseek_vit_412m_enc(pretrained=False, **kwargs):
    return _create_deepseek_vit_encoder('deepseek_vit_412m_enc', pretrained=pretrained, **kwargs)
