from typing import Any, Callable, List, Optional
import torch
from torch import Tensor, nn
import torch.nn.functional as F
from collections import OrderedDict
from functools import partial
from torch.utils.checkpoint import checkpoint_sequential
from torchvision.ops import Conv2dNormActivation

def channel_shuffle(x, groups):
    batchsize, num_channels, height, width = x.size()
    channels_per_group = num_channels // groups
    x = x.view(batchsize, groups, channels_per_group, height, width)
    x = torch.transpose(x, 1, 2).contiguous()
    x = x.view(batchsize, -1, height, width)
    return x

class ShuffleResidual(nn.Module):

    def __init__(self, inp, oup, stride):
        super().__init__()
        self.stride = stride
        branch_features = oup // 2
        if self.stride > 1:
            self.branch1 = nn.Sequential(self.depthwise_conv(inp, inp, kernel_size=3, stride=self.stride, padding=1), nn.BatchNorm2d(inp), nn.Conv2d(inp, branch_features, kernel_size=1, bias=False), nn.BatchNorm2d(branch_features), nn.ReLU(inplace=True))
        else:
            self.branch1 = nn.Sequential()
        self.branch2 = nn.Sequential(nn.Conv2d(inp if self.stride > 1 else branch_features, branch_features, kernel_size=1, bias=False), nn.BatchNorm2d(branch_features), nn.ReLU(inplace=True), self.depthwise_conv(branch_features, branch_features, kernel_size=3, stride=self.stride, padding=1), nn.BatchNorm2d(branch_features), nn.Conv2d(branch_features, branch_features, kernel_size=1, bias=False), nn.BatchNorm2d(branch_features), nn.ReLU(inplace=True))

    @staticmethod
    def depthwise_conv(i, o, kernel_size, stride=1, padding=0, bias=False):
        return nn.Conv2d(i, o, kernel_size, stride, padding, bias=bias, groups=i)

    def forward(self, tensor):
        if self.stride == 1:
            x1, x2 = tensor.chunk(2, dim=1)
            out = torch.cat((x1, self.branch2(x2)), dim=1)
        else:
            out = torch.cat((self.branch1(tensor), self.branch2(tensor)), dim=1)
        out = channel_shuffle(out, 2)
        return out

def conv3x3(in_planes, out_planes, stride=1, groups=1):
    return nn.Conv2d(in_planes, out_planes, kernel_size=3, stride=stride, padding=1, groups=groups, bias=False)

def conv1x1(in_planes, out_planes, stride=1):
    return nn.Conv2d(in_planes, out_planes, kernel_size=1, stride=stride, bias=False)

class BottleneckBlock(nn.Module):
    expansion = 4

    def __init__(self, inplanes, planes, stride=1, downsample=None, norm_layer=None):
        super().__init__()
        if norm_layer is None:
            norm_layer = nn.BatchNorm2d
        self.conv_a = conv1x1(inplanes, planes)
        self.norm1 = norm_layer(planes)
        self.conv_b = conv3x3(planes, planes, stride)
        self.norm2 = norm_layer(planes)
        self.conv_c = conv1x1(planes, planes * self.expansion)
        self.norm3 = norm_layer(planes * self.expansion)
        self.downsample = downsample
        self.stride = stride

    def forward(self, tensor):
        residual = tensor
        y = self.conv_a(tensor)
        y = self.norm1(y)
        y = F.silu(y)
        y = self.conv_b(y)
        y = self.norm2(y)
        y = F.silu(y)
        y = self.conv_c(y)
        y = self.norm3(y)
        if self.downsample is not None:
            residual = self.downsample(tensor)
        y += residual
        y = F.silu(y)
        return y

def downsample_conv(in_chs, out_chs, stride=1, norm_layer=None):
    if norm_layer is None:
        norm_layer = nn.BatchNorm2d
    return nn.Sequential(nn.Conv2d(in_chs, out_chs, kernel_size=1, stride=stride, bias=False), norm_layer(out_chs))

def downsample_avg(in_chs, out_chs, stride=1, norm_layer=None):
    if norm_layer is None:
        norm_layer = nn.BatchNorm2d
    pool = nn.AvgPool2d(2, stride, ceil_mode=True, count_include_pad=False) if stride > 1 else nn.Identity()
    return nn.Sequential(pool, nn.Conv2d(in_chs, out_chs, kernel_size=1, stride=1, bias=False), norm_layer(out_chs))

class Head(nn.Module):

    def __init__(self, in_features, num_classes, drop_rate=0.0):
        super().__init__()
        self.global_pool = nn.AdaptiveAvgPool2d(1)
        self.flatten = nn.Flatten(1)
        self.drop = nn.Dropout(drop_rate)
        self.fc = nn.Linear(in_features, num_classes) if num_classes > 0 else nn.Identity()

    def forward(self, x, pre_logits=False):
        x = self.global_pool(x)
        x = self.flatten(x)
        x = self.drop(x)
        return x if pre_logits else self.fc(x)

class TinyNet(nn.Module):

    def __init__(self, conv_cfg, block_cfg, in_chans=3, num_classes=1000, drop_rate=0.0, norm_layer=None, down_type='avg', **kwargs):
        super().__init__()
        if norm_layer is None:
            norm_layer = partial(nn.BatchNorm2d, eps=0.001)
        self.num_classes = num_classes
        self.stem = nn.Sequential(OrderedDict([('conv', nn.Conv2d(in_chans, 8, kernel_size=3, stride=2, padding=1, bias=False)), ('bn', norm_layer(8)), ('act', nn.SiLU())]))
        in_ch = 8
        blocks = []
        for idx, (c, n) in enumerate(conv_cfg):
            blocks.append(ShuffleResidual(in_ch, c, 2))
            for _ in range(n - 1):
                blocks.append(ShuffleResidual(c, c, 1))
            in_ch = c
        for idx, (planes, n, stride) in enumerate(block_cfg, start=len(conv_cfg)):
            downsample = None
            if stride != 1 or in_ch != planes * BottleneckBlock.expansion:
                down_fn = downsample_avg if down_type == 'avg' else downsample_conv
                downsample = down_fn(in_ch, planes * BottleneckBlock.expansion, stride, norm_layer)
            blocks.append(BottleneckBlock(in_ch, planes, stride, downsample))
            in_ch = planes * BottleneckBlock.expansion
            for _ in range(1, n):
                blocks.append(BottleneckBlock(in_ch, planes))
        self.features = nn.Sequential(*blocks)
        self.grad_checkpointing = False
        self.conv_head = Conv2dNormActivation(in_ch, 64, kernel_size=1)
        in_ch = 64
        self.head = Head(in_ch, num_classes, drop_rate=drop_rate)

    def forward(self, tensor):
        torch._assert(tensor.dim() == 4, f'expected a 4D input, got {tensor.dim()}D')
        tensor = self.stem(tensor)
        if self.grad_checkpointing and (not torch.jit.is_scripting()):
            tensor = checkpoint_sequential(self.features, len(self.features), tensor)
        else:
            tensor = self.features(tensor)
        tensor = self.conv_head(tensor)
        return self.head(tensor)

def _tinynet(variant, weights=None, progress=True, **kwargs):
    cfgs = {'small': ([(16, 2), (32, 2)], [(32, 2, 2)]), 'base': ([(16, 3), (32, 3)], [(32, 3, 2)])}
    model = TinyNet(*cfgs[variant], **kwargs)
    if weights is not None:
        model.load_state_dict(weights.get_state_dict(progress=progress))
    return model

def make_model(weights=None, progress=True, **kwargs):
    return _tinynet('base', weights, progress, **kwargs)
