    def __init__(self, c, n, in_ch):
        super(ResStage, self).__init__()
        blocks = []
        blocks.append(ShuffleBlock(in_ch, c, 2))
        for _ in range(n - 1):
            blocks.append(ShuffleBlock(c, c, 1))
        in_ch = c
        self.blocks = nn.Sequential(*blocks)
        self.out_channels = in_ch

    def forward(self, x):
        return self.blocks(x)

class Model(nn.Module):

    def __init__(self, arch, in_chans=3, num_classes=1000, drop_rate=0.0, norm_layer=None, output_stride=32):
        super(Model, self).__init__()
        assert output_stride in (8, 16, 32)
        if norm_layer is None:
            norm_layer = partial(nn.BatchNorm2d, eps=0.001)
        self.num_classes = num_classes
        self.stem = Conv2dBNAct(in_chans, 8, kernel_size=3, stride=2)
        in_ch = 8
        stages = []
        for idx, (c, n) in enumerate(arch):
            stage = ResStage(c, n, in_ch)
            stages.append(stage)
            in_ch = stage.out_channels
        self.stages = nn.Sequential(*stages)
        self.flatten = nn.Flatten(1)
        self.drop = nn.Identity()
        self.fc = nn.Linear(in_ch, num_classes)

    def forward_features(self, inp):
        inp = self.stem(inp)
        inp = self.stages(inp)
        return inp

    def forward_head(self, inp, pre_logits=False):
        inp = F.adaptive_avg_pool2d(inp, 1)
        inp = self.flatten(inp)
        inp = self.drop(inp)
        return inp if pre_logits else self.fc(inp)

    def forward(self, inp):
        inp = self.forward_features(inp)
        inp = self.forward_head(inp)
        return inp

def build_model(variant='small', **kwargs):
    cfgs = {'small': [(16, 1), (32, 2), (64, 1), (128, 3)], 'base': [(16, 2), (32, 3), (64, 2), (128, 4)]}
    return Model(cfgs[variant], **kwargs)
