        self.grad_checkpointing = False
        self.use_nchw = not issubclass(token_mixer, Attention)
        self.downsample = nn.Identity() if in_chs == out_chs else Downsampling(in_chs, out_chs, kernel_size=3, stride=2, padding=1, norm_layer=downsample_norm, **dd)
        self.blocks = nn.Sequential(*[MetaFormerBlock(dim=out_chs, token_mixer=token_mixer, mlp_act=mlp_act, mlp_bias=mlp_bias, norm_layer=norm_layer, proj_drop=proj_drop, drop_path=dp_rates[i], layer_scale_init_value=layer_scale_init_value, res_scale_init_value=res_scale_init_value, use_nchw=self.use_nchw, **dd, **kwargs) for i in range(depth)])

