from functools import partial
from typing import Any, Dict, List, Optional, Set, Tuple, Type, Union
import torch
import torch.nn as nn
from torch.nn.utils.fusion import fuse_conv_bn_eval
from timm.data import IMAGENET_DEFAULT_MEAN, IMAGENET_DEFAULT_STD
from timm.layers import DropPath, LayerNorm, LayerNorm2d, SqueezeExcite, calculate_drop_path_rates, trunc_normal_, get_device_dtype
from ._builder import build_model_with_cfg
from ._features import feature_take_indices
from ._manipulate import checkpoint
from ._registry import register_model, generate_default_cfgs

class ConvLayer1d(nn.Module):

    def __init__(self, in_dim, out_dim, kernel_size=3, stride=1, padding=0, dilation=1, groups=1, norm=nn.BatchNorm1d, act_layer=nn.ReLU, bn_weight_init=1.0, device=None, dtype=None):
        super().__init__()
        dd = {'device': device, 'dtype': dtype}
        self.conv = nn.Conv1d(in_dim, out_dim, kernel_size, stride=stride, padding=padding, dilation=dilation, groups=groups, bias=False, **dd)
        self.norm = norm(out_dim, **dd) if norm else None
        self.act = act_layer() if act_layer else None

    @torch.no_grad()
    def fuse(self):
        if isinstance(self.norm, nn.modules.batchnorm._BatchNorm):
            self.conv = fuse_conv_bn_eval(self.conv, self.norm)
            self.norm = None
        return self

    def forward(self, x):
        x = self.conv(x)
        if self.norm is not None:
            x = self.norm(x)
        if self.act is not None:
            x = self.act(x)
        return x

class ConvLayer2d(nn.Module):

    def __init__(self, in_dim, out_dim, kernel_size=3, stride=1, padding=0, dilation=1, groups=1, norm=nn.BatchNorm2d, act_layer=nn.ReLU, bn_weight_init=1.0, device=None, dtype=None):
        super().__init__()
        dd = {'device': device, 'dtype': dtype}
        self.conv = nn.Conv2d(in_dim, out_dim, kernel_size, stride=stride, padding=padding, dilation=dilation, groups=groups, bias=False, **dd)
        self.norm = norm(out_dim, **dd) if norm else None
        self.act = act_layer() if act_layer else None

    @torch.no_grad()
    def fuse(self):
        if isinstance(self.norm, nn.modules.batchnorm._BatchNorm):
            self.conv = fuse_conv_bn_eval(self.conv, self.norm)
            self.norm = None
        return self

    def forward(self, x):
        x = self.conv(x)
        if self.norm is not None:
            x = self.norm(x)
        if self.act is not None:
            x = self.act(x)
        return x

class Stem(nn.Module):

    def __init__(self, in_dim, dim, device=None, dtype=None):
        super().__init__()
        dd = {'device': device, 'dtype': dtype}
        self.conv = nn.Sequential(ConvLayer2d(in_dim, dim // 8, kernel_size=3, stride=2, padding=1, **dd), ConvLayer2d(dim // 8, dim // 4, kernel_size=3, stride=2, padding=1, **dd), ConvLayer2d(dim // 4, dim // 2, kernel_size=3, stride=2, padding=1, **dd), ConvLayer2d(dim // 2, dim, kernel_size=3, stride=2, padding=1, act_layer=None, **dd))

    def forward(self, x):
        return self.conv(x)

class FFN(nn.Module):

    def __init__(self, in_dim, dim, device=None, dtype=None):
        super().__init__()
        dd = {'device': device, 'dtype': dtype}
        self.fc1 = ConvLayer2d(in_dim, dim, 1, **dd)
        self.fc2 = ConvLayer2d(dim, in_dim, 1, act_layer=None, bn_weight_init=0, **dd)

    def forward(self, x):
        return self.fc2(self.fc1(x))

@torch.no_grad()
def _fuse_depthwise_residual(conv, scale=None):
    assert conv.groups == conv.in_channels == conv.out_channels
    assert conv.stride == (1, 1) and conv.dilation == (1, 1)
    kh, kw = conv.kernel_size
    if scale is None:
        conv.weight[:, 0, kh // 2, kw // 2] += 1
    else:
        scale = scale.reshape(-1)
        conv.weight.mul_(scale[:, None, None, None])
        if conv.bias is not None:
            conv.bias.mul_(scale)
        conv.weight[:, 0, kh // 2, kw // 2] += 1 - scale

class PatchMerging(nn.Module):

    def __init__(self, in_dim, out_dim, ratio=4.0, device=None, dtype=None):
        super().__init__()
        dd = {'device': device, 'dtype': dtype}
        self.fused = False
        hidden_dim = int(out_dim * ratio)
        self.conv = nn.Sequential(ConvLayer2d(in_dim, hidden_dim, kernel_size=1, **dd), ConvLayer2d(hidden_dim, hidden_dim, kernel_size=3, stride=2, padding=1, groups=hidden_dim, **dd), SqueezeExcite(hidden_dim, 0.25, **dd), ConvLayer2d(hidden_dim, out_dim, kernel_size=1, act_layer=None, **dd))
        self.dwconv1 = ConvLayer2d(in_dim, in_dim, 3, padding=1, groups=in_dim, act_layer=None, **dd)
        self.dwconv2 = ConvLayer2d(out_dim, out_dim, 3, padding=1, groups=out_dim, act_layer=None, **dd)

    @torch.no_grad()
    def fuse(self):
        if not self.fused:
            assert not self.training, 'Fusion requires evaluation mode.'
            self.dwconv1.fuse()
            self.dwconv2.fuse()
            _fuse_depthwise_residual(self.dwconv1.conv)
            _fuse_depthwise_residual(self.dwconv2.conv)
            self.fused = True
        return self

    def forward(self, x):
        x = self.dwconv1(x) if self.fused else x + self.dwconv1(x)
        x = self.conv(x)
        x = self.dwconv2(x) if self.fused else x + self.dwconv2(x)
        return x

class HSMSSD(nn.Module):

    def __init__(self, dim, ssd_expand=1.0, state_dim=64, a_init_range=(1.0, 16.0), device=None, dtype=None):
        super().__init__()
        dd = {'device': device, 'dtype': dtype}
        self.ssd_expand = ssd_expand
        self.d_inner = int(self.ssd_expand * dim)
        self.state_dim = state_dim
        self.BCdt_proj = ConvLayer1d(dim, 3 * state_dim, 1, norm=None, act_layer=None, **dd)
        conv_dim = self.state_dim * 3
        self.dw = ConvLayer2d(conv_dim, conv_dim, 3, 1, 1, groups=conv_dim, norm=None, act_layer=None, bn_weight_init=0, **dd)
        self.hz_proj = ConvLayer1d(dim, 2 * self.d_inner, 1, norm=None, act_layer=None, **dd)
        self.out_proj = ConvLayer1d(self.d_inner, dim, 1, norm=None, act_layer=None, bn_weight_init=0, **dd)
        self.a_init_range = a_init_range
        self.A = nn.Parameter(torch.empty(self.state_dim, **dd))
        self.act = nn.SiLU()
        self.D = nn.Parameter(torch.ones(1, device=device, dtype=dtype))
        self.reset_parameters()

    def reset_parameters(self):
        pass

    def forward(self, x):
        batch, _, height, width = x.shape
        x = x.flatten(2)
        BCdt = self.dw(self.BCdt_proj(x).reshape(batch, -1, height, width)).flatten(2)
        b, c, dt = torch.split(BCdt, [self.state_dim, self.state_dim, self.state_dim], dim=1)
        a = (dt + self.A.view(1, -1, 1)).softmax(-1)
        ab = a * b
        h = x @ ab.transpose(-2, -1)
        h, z = torch.split(self.hz_proj(h), [self.d_inner, self.d_inner], dim=1)
        h = self.out_proj(h * self.act(z) + h * self.D)
        y = h @ c
        y = y.reshape(batch, -1, height, width).contiguous()
        return (y, h)

class EfficientViMBlock(nn.Module):

    def __init__(self, dim, mlp_ratio=4.0, ssd_expand=1.0, state_dim=64, drop_path=0.0, device=None, dtype=None):
        super().__init__()
        dd = {'device': device, 'dtype': dtype}
        self.fused = False
        self.mixer = HSMSSD(dim, ssd_expand=ssd_expand, state_dim=state_dim, **dd)
        self.norm = LayerNorm2d(dim, eps=1e-05, **dd)
        self.dwconv1 = ConvLayer2d(dim, dim, 3, padding=1, groups=dim, bn_weight_init=0, act_layer=None, **dd)
        self.dwconv2 = ConvLayer2d(dim, dim, 3, padding=1, groups=dim, bn_weight_init=0, act_layer=None, **dd)
        self.ffn = FFN(dim, int(dim * mlp_ratio), **dd)
        self.alpha = nn.Parameter(0.0001 * torch.ones(4, dim, device=device, dtype=dtype), requires_grad=True)
        self.drop_path = DropPath(drop_path) if drop_path > 0.0 else nn.Identity()

    def reset_parameters(self):
        pass

    @torch.no_grad()
    def fuse(self):
        if not self.fused:
            assert not self.training, 'Fusion requires evaluation mode.'
            alpha = self.alpha.detach().sigmoid()
            self.dwconv1.fuse()
            self.dwconv2.fuse()
            _fuse_depthwise_residual(self.dwconv1.conv, alpha[0])
            _fuse_depthwise_residual(self.dwconv2.conv, alpha[2])
            self.fused = True
        return self

    def forward(self, x):
        alpha = torch.sigmoid(self.alpha).view(4, -1, 1, 1)
        x = self.dwconv1(x) if self.fused else x + self.drop_path(alpha[0] * (self.dwconv1(x) - x))
        x_prev = x
        x, h = self.mixer(self.norm(x))
        x = x_prev + self.drop_path(alpha[1] * (x - x_prev))
        x = self.dwconv2(x) if self.fused else x + self.drop_path(alpha[2] * (self.dwconv2(x) - x))
        x = x + self.drop_path(alpha[3] * (self.ffn(x) - x))
        return (x, h)

class EfficientViMStage(nn.Module):

    def __init__(self, in_dim, out_dim, depth, mlp_ratio=4.0, downsample=None, ssd_expand=1.0, state_dim=64, drop_path=None, device=None, dtype=None):
        super().__init__()
        assert depth > 0
        self.depth = depth
        self.grad_checkpointing = False
        drop_path = drop_path or [0.0] * depth
        self.blocks = nn.ModuleList([EfficientViMBlock(dim=in_dim, mlp_ratio=mlp_ratio, ssd_expand=ssd_expand, state_dim=state_dim, drop_path=drop_path[i], device=device, dtype=dtype) for i in range(depth)])
        self.downsample = downsample(in_dim=in_dim, out_dim=out_dim, device=device, dtype=dtype) if downsample is not None else None

    def forward(self, x):
        h = None
        for blk in self.blocks:
            if self.grad_checkpointing and (not torch.jit.is_scripting()):
                x, h = checkpoint(blk, x)
            else:
                x, h = blk(x)
        x_out = x
        if self.downsample is not None:
            x = self.downsample(x)
        return (x_out, x, h)

class EfficientViM(nn.Module):

    def __init__(self, in_chans=3, num_classes=1000, embed_dim=(128, 256, 512), depths=(2, 2, 2), mlp_ratio=4.0, ssd_expand=1.0, state_dim=(49, 25, 9), global_pool='avg', drop_rate=0.0, drop_path_rate=0.0, device=None, dtype=None):
        super().__init__()
        dd = {'device': device, 'dtype': dtype}
        assert global_pool in ('avg', '')
        assert global_pool or num_classes == 0
        assert len(depths) == len(embed_dim) == len(state_dim)
        self.in_chans = in_chans
        self.global_pool = global_pool
        self.num_classes = num_classes
        self.num_layers = len(depths)
        self.embed_dim = tuple(embed_dim)
        self.grad_checkpointing = False
        self.feature_info = []
        self.patch_embed = Stem(in_dim=in_chans, dim=embed_dim[0], **dd)
        dpr = calculate_drop_path_rates(drop_path_rate, sum(depths))
        stages = []
        block_idx = 0
        reduction = 16
        for i_layer in range(self.num_layers):
            stage_dpr = dpr[block_idx:block_idx + depths[i_layer]]
            block_idx += depths[i_layer]
            stages.append(EfficientViMStage(in_dim=int(embed_dim[i_layer]), out_dim=int(embed_dim[i_layer + 1]) if i_layer < self.num_layers - 1 else 0, depth=depths[i_layer], mlp_ratio=mlp_ratio, downsample=PatchMerging if i_layer < self.num_layers - 1 else None, ssd_expand=ssd_expand, state_dim=state_dim[i_layer], drop_path=stage_dpr, **dd))
            self.feature_info.append(dict(num_chs=embed_dim[i_layer], reduction=reduction, module=f'stages.{i_layer}'))
            if i_layer < self.num_layers - 1:
                reduction *= 2
        self.stages = nn.ModuleList(stages)
        self.num_features = self.head_hidden_size = sum(embed_dim) + embed_dim[-1]
        self.weights = nn.Parameter(torch.ones(self.num_layers + 1, **dd), requires_grad=num_classes > 0)
        self.norm = nn.ModuleList([*[LayerNorm(dim, eps=1e-05, **dd) for dim in embed_dim], LayerNorm2d(embed_dim[-1], eps=1e-05, **dd)])
        self.head_drop = nn.Dropout(drop_rate)
        self.heads = self._build_heads(num_classes, dd)

    def _build_heads(self, num_classes, dd=None):
        dd = dd or {}
        return nn.ModuleList([nn.Linear(dim, num_classes, **dd) if num_classes > 0 else nn.Identity() for dim in (*self.embed_dim, self.embed_dim[-1])])

    def _init_weights(self, m, needs_reset=True):
        if isinstance(m, nn.Linear):
            pass
        elif isinstance(m, (nn.LayerNorm, nn.BatchNorm2d, nn.BatchNorm1d)):
            m.reset_parameters()
        elif needs_reset and hasattr(m, 'reset_parameters'):
            m.reset_parameters()

    def forward_features(self, x):
        x = self.patch_embed(x)
        features = []
        for stage, norm in zip(self.stages, self.norm):
            _, x, h = stage(x)
            features.append(norm(h.transpose(1, 2)).transpose(1, 2))
        features.append(self.norm[-1](x).flatten(2))
        return features

    def forward_head(self, x, pre_logits=False):
        if not self.global_pool:
            return x
        x = [self.head_drop(t.mean(-1)) for t in x]
        if pre_logits or self.num_classes == 0:
            return torch.cat(x, dim=1)
        weights = self.weights.softmax(-1)
        logits = [weights[i] * head(x[i]) for i, head in enumerate(self.heads)]
        return torch.stack(logits).sum(0)

    def forward(self, x):
        x = self.forward_features(x)
        return self.forward_head(x)

class EfficientViMDistilled(EfficientViM):

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        dd = get_device_dtype(self)
        num_classes = self.num_classes
        self.weights_dist = nn.Parameter(torch.ones(self.num_layers + 1, **dd), requires_grad=num_classes > 0)
        self.heads_dist = self._build_heads(num_classes, dd)
        self.heads_dist.apply(self._init_weights)
        self.distilled_training = False

    def forward_head(self, x, pre_logits=False):
        if not self.global_pool:
            return x
        x = [self.head_drop(t.mean(-1)) for t in x]
        if pre_logits or self.num_classes == 0:
            return torch.cat(x, dim=1)
        weights = self.weights.softmax(-1)
        weights_dist = self.weights_dist.softmax(-1)
        logits = [weights[i] * head(x[i]) for i, head in enumerate(self.heads)]
        logits_dist = [weights_dist[i] * head(x[i]) for i, head in enumerate(self.heads_dist)]
        z, z_dist = (torch.stack(logits).sum(0), torch.stack(logits_dist).sum(0))
        if self.distilled_training and self.training and (not torch.jit.is_scripting()):
            return (z, z_dist)
        return (z + z_dist) / 2

def checkpoint_filter_fn(state_dict, model):
    if 'patch_embed.conv.0.conv.weight' not in state_dict:
        for envelope_key in ('model_ema', 'model', 'state_dict'):
            if isinstance(state_dict.get(envelope_key), dict):
                state_dict = state_dict[envelope_key]
                break
    if not isinstance(model, EfficientViMDistilled):
        state_dict = {k: v for k, v in state_dict.items() if not (k.startswith('heads_dist.') or k == 'weights_dist')}
    state_dict = dict(state_dict)
    for name, module in model.named_modules():
        if isinstance(module, nn.LayerNorm):
            for suffix in ('weight', 'bias'):
                key = f'{name}.{suffix}'
                if key in state_dict:
                    state_dict[key] = state_dict[key].reshape(module.normalized_shape)
    return state_dict

def _create_efficientvim(variant, pretrained=False, distilled=False, **kwargs):
    feature_cfg = dict(out_indices=(0, 1, 2), feature_cls='getter')
    return build_model_with_cfg(EfficientViMDistilled if distilled else EfficientViM, variant, pretrained, pretrained_filter_fn=checkpoint_filter_fn, feature_cfg=feature_cfg, **kwargs)

