class EfficientViMStage(nn.Module):

    def __init__(self, in_dim, out_dim, depth, mlp_ratio=4.0, downsample=None, ssd_expand=1.0, state_dim=64, drop_path=None, device=None, dtype=None):
        super().__init__()
        assert depth > 0
        self.depth = depth
        self.grad_checkpointing = False
        drop_path = drop_path or [0.0] * depth
        self.blocks = nn.ModuleList([EfficientViMBlock(dim=in_dim, mlp_ratio=mlp_ratio, ssd_expand=ssd_expand, state_dim=state_dim, drop_path=drop_path[i], device=device, dtype=dtype) for i in range(depth)])
        self.downsample = downsample(in_dim=in_dim, out_dim=out_dim, device=device, dtype=dtype) if downsample is not None else None

    def forward(self, x):
        h = None
        for blk in self.blocks:
            if self.grad_checkpointing and (not torch.jit.is_scripting()):
                x, h = checkpoint(blk, x)
            else:
                x, h = blk(x)
        x_out = x
        if self.downsample is not None:
            x = self.downsample(x)
        return (x_out, x, h)
