from typing import Any, Callable, List, Optional
import torch
from torch import Tensor, nn
import torch.nn.functional as F

class ConvBNReLU(nn.Module):

    def __init__(self, in_channels, out_channels, kernel_size=3, stride=1, groups=1, act=True):
        super(ConvBNReLU, self).__init__()
        padding = (kernel_size - 1) // 2 if isinstance(kernel_size, int) else tuple(((k - 1) // 2 for k in kernel_size))
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size, stride=stride, padding=padding, groups=groups, bias=False)
        self.bn = nn.BatchNorm2d(out_channels)
        self.use_act = act
        self.act = nn.ReLU6(inplace=True)

    def forward(self, tensor):
        tensor = self.conv(tensor)
        tensor = self.bn(tensor)
        if self.use_act:
            tensor = self.act(tensor)
        return tensor

class SEBlock(nn.Module):

    def __init__(self, channels, squeeze_channels):
        super(SEBlock, self).__init__()
        self.avgpool = nn.AdaptiveAvgPool2d(1)
        self.fc1 = nn.Conv2d(channels, squeeze_channels, 1)
        self.fc2 = nn.Conv2d(squeeze_channels, channels, 1)
        self.activation = nn.ReLU()
        self.scale_activation = nn.Sigmoid()

    def forward(self, tensor):
        scale = self.avgpool(tensor)
        scale = self.fc1(scale)
        scale = self.activation(scale)
        scale = self.fc2(scale)
        scale = self.scale_activation(scale)
        return scale * tensor

class InvertedResidual(nn.Module):

    def __init__(self, inp, oup, stride, expand_ratio, use_se=False, norm_layer=None):
        super(InvertedResidual, self).__init__()
        self.stride = stride
        if norm_layer is None:
            norm_layer = nn.BatchNorm2d
        hidden_dim = int(round(inp * expand_ratio))
        self.residual = self.stride == 1 and inp == oup
        layers = []
        if expand_ratio != 1:
            layers.append(ConvBNReLU(inp, hidden_dim, kernel_size=1))
        layers.append(ConvBNReLU(hidden_dim, hidden_dim, kernel_size=5, stride=stride, groups=hidden_dim))
        if use_se:
            layers.append(SEBlock(hidden_dim, max(1, hidden_dim // 4)))
        layers.append(nn.Conv2d(hidden_dim, oup, 1, 1, 0, bias=False))
        layers.append(norm_layer(oup))
        self.conv = nn.Sequential(*layers)

    def forward(self, tensor):
        out = self.conv(tensor)
        if self.residual:
            out = out + tensor
        return out

def make_divisible(v, divisor=8, min_value=None):
    if min_value is None:
        min_value = divisor
    new_v = max(min_value, int(v + divisor / 2) // divisor * divisor)
    if new_v < 0.9 * v:
        new_v += divisor
    return new_v

class NetStage(nn.Module):

    def __init__(self, t, c, n, stride, se, in_ch, width_mult=1.0):
        super(NetStage, self).__init__()
        blocks = []
        out_c = make_divisible(c * width_mult, 8)
        for i in range(n):
            blocks.append(InvertedResidual(in_ch, out_c, stride if i == 0 else 1, t, use_se=se))
            in_ch = out_c
        self.layers = nn.Sequential(*blocks)
        self.out_channels = in_ch

    def forward(self, x):
        return self.layers(x)

class PoolHead(nn.Module):

    def __init__(self, in_features, num_classes, drop_rate=0.0):
        super(PoolHead, self).__init__()
        self.global_pool = nn.AdaptiveAvgPool2d(1)
        self.flatten = nn.Flatten(1)
        self.drop = nn.Dropout(drop_rate)
        self.fc = nn.Linear(in_features, num_classes) if num_classes > 0 else nn.Identity()

    def forward(self, x, pre_logits=False):
        x = self.global_pool(x)
        x = self.flatten(x)
        x = self.drop(x)
        return x if pre_logits else self.fc(x)

class ConvNet(nn.Module):

    def __init__(self, settings, in_chans=3, num_classes=100, drop_rate=0.0, width_mult=1.0, norm_layer=None, **kwargs):
        super(ConvNet, self).__init__()
        if norm_layer is None:
            norm_layer = nn.BatchNorm2d
        self.num_classes = num_classes
        self.stem = ConvBNReLU(in_chans, 8, kernel_size=3, stride=2)
        in_ch = 8
        stages = []
        for idx, (t, c, n, stride, se) in enumerate(settings):
            stage = NetStage(t, c, n, stride, se, in_ch)
            stages.append(stage)
            in_ch = stage.out_channels
        self.stages = nn.ModuleList(stages)
        self.head = PoolHead(in_ch, num_classes, drop_rate=drop_rate)

    def forward_features(self, tensor):
        tensor = self.stem(tensor)
        for stage in self.stages:
            tensor = stage(tensor)
        return tensor

    def forward_head(self, tensor, pre_logits=False):
        return self.head(tensor, pre_logits=pre_logits)

    def forward(self, tensor):
        tensor = self.forward_features(tensor)
        tensor = self.forward_head(tensor)
        return tensor

def _convnet(variant, weights=None, progress=True, **kwargs):
    cfgs = {'small': [(1, 16, 1, 1, False), (3, 24, 3, 2, False), (6, 32, 3, 2, False)], 'base': [(1, 16, 2, 1, False), (3, 24, 4, 2, False), (6, 32, 4, 2, False)]}
    model = ConvNet(cfgs[variant], **kwargs)
    if weights is not None:
        model.load_state_dict(weights.get_state_dict(progress=progress))
    return model

def convnet_tiny(weights=None, progress=True, **kwargs):
    return _convnet('base', weights, progress, **kwargs)
