import torch
import torch.nn as nn
import torch.nn.functional as F
from torchvision.ops import SqueezeExcitation
from functools import partial
from collections import OrderedDict

def adjust_width(width, group_width):
    group_width = min(group_width, width)
    return int(round(width / group_width) * group_width)

class ResBottleneckBlock(nn.Module):

    def __init__(self, in_ch, out_ch, stride, group_width, bottleneck_ratio=1.0, se_ratio=None):
        super().__init__()
        w_b = int(round(out_ch * bottleneck_ratio))
        groups = w_b // group_width
        self.f_a = nn.Sequential(nn.Conv2d(in_ch, w_b, 1, bias=False), nn.BatchNorm2d(w_b), nn.SiLU())
        self.f_b = nn.Sequential(nn.Conv2d(w_b, w_b, 3, stride=stride, padding=1, groups=groups, bias=False), nn.BatchNorm2d(w_b), nn.SiLU())
        self.se = SqueezeExcitation(w_b, max(1, int(round(se_ratio * in_ch)))) if se_ratio else None
        self.f_c = nn.Sequential(nn.Conv2d(w_b, out_ch, 1, bias=False), nn.BatchNorm2d(out_ch))
        self.downsample = None
        if in_ch != out_ch or stride != 1:
            self.downsample = nn.Sequential(nn.Conv2d(in_ch, out_ch, 1, stride=stride, bias=False), nn.BatchNorm2d(out_ch))
        self.act = nn.SiLU()

    def forward(self, z):
        shortcut = z if self.downsample is None else self.downsample(z)
        z = self.f_a(z)
        z = self.f_b(z)
        if self.se is not None:
            z = self.se(z)
        z = self.f_c(z)
        return self.act(z + shortcut)

class ResStage(nn.Module):

    def __init__(self, w, d, g, in_ch):
        super().__init__()
        blocks = []
        w = adjust_width(w, g)
        for i in range(d):
            blocks.append(ResBottleneckBlock(in_ch, w, 2 if i == 0 else 1, g, se_ratio=0.25))
            in_ch = w
        self.layers = nn.Sequential(*blocks)
        self.out_channels = in_ch

    def forward(self, x):
        return self.layers(x)

class Net(nn.Module):

    def __init__(self, cfg, in_chans=3, num_classes=10, drop_rate=0.0, norm_layer=None, **kwargs):
        super().__init__()
        if norm_layer is None:
            norm_layer = partial(nn.BatchNorm2d, eps=0.001)
        self.num_classes = num_classes
        self.conv_stem = nn.Conv2d(in_chans, 8, kernel_size=3, stride=2, padding=1, bias=False)
        self.bn1 = norm_layer(8)
        self.act1 = nn.SiLU()
        in_ch = 8
        stages = []
        for idx, (w, d, g) in enumerate(cfg):
            stage = ResStage(w, d, g, in_ch)
            stages.append(stage)
            in_ch = stage.out_channels
        self.stages = nn.ModuleList(stages)
        self.classifier = nn.Sequential(OrderedDict([('flatten', nn.Flatten(1)), ('drop', nn.Dropout(p=drop_rate)), ('fc', nn.Linear(in_ch, num_classes))]))

    def forward(self, z):
        z = self.conv_stem(z)
        z = self.bn1(z)
        z = self.act1(z)
        for stage in self.stages:
            z = stage(z)
        z = F.adaptive_avg_pool2d(z, 1)
        return self.classifier(z)

def _net(variant, weights=None, progress=True, **kwargs):
    cfgs = {'small': [(24, 1, 8), (32, 2, 8), (56, 2, 8)]}
    model = Net(cfgs[variant], **kwargs)
    if weights is not None:
        model.load_state_dict(weights.get_state_dict(progress=progress))
    return model

def net_tiny(weights=None, progress=True, **kwargs):
    return _net('small', weights, progress, **kwargs)
