        self.act2 = act_layer()
        self.se = SqueezeExcite(hid_dim, 0.25, **dd)
        self.conv3 = Conv2dNorm(hid_dim, out_dim, **dd)

    def forward(self, x):
        x = self.conv1(x)
        x = self.act1(x)
        x = self.conv2(x)
        x = self.act2(x)
        x = self.se(x)
        x = self.conv3(x)
        return x

