        self.blocks = nn.Sequential(*[BasicBlock(dim, qk_dim, pdim, type, norm_layer, act_layer, **dd) for _ in range(depth)])

    def forward(self, x):
        x = self.downsample(x)
        if self.grad_checkpointing and (not torch.jit.is_scripting()):
            x = checkpoint_seq(self.blocks, x)
        else:
            x = self.blocks(x)
        return x

class SHViT(nn.Module):

    def __init__(self, in_chans=3, num_classes=1000, global_pool='avg', embed_dim=(128, 256, 384), partial_dim=(32, 64, 96), qk_dim=(16, 16, 16), depth=(1, 2, 3), types=('s', 's', 's'), drop_rate=0.0, norm_layer=GroupNorm1, act_layer=nn.ReLU, device=None, dtype=None):
        super().__init__()
        dd = {'device': device, 'dtype': dtype}
        self.num_classes = num_classes
        self.in_chans = in_chans
        self.drop_rate = drop_rate
        self.feature_info = []
        stem_chs = embed_dim[0]
        self.patch_embed = nn.Sequential(Conv2dNorm(in_chans, stem_chs // 8, 3, 2, 1, **dd), act_layer(), Conv2dNorm(stem_chs // 8, stem_chs // 4, 3, 2, 1, **dd), act_layer(), Conv2dNorm(stem_chs // 4, stem_chs // 2, 3, 2, 1, **dd), act_layer(), Conv2dNorm(stem_chs // 2, stem_chs, 3, 2, 1, **dd))
        stages = []
        prev_chs = stem_chs
        for i in range(len(embed_dim)):
            stages.append(StageBlock(prev_dim=prev_chs, dim=embed_dim[i], qk_dim=qk_dim[i], pdim=partial_dim[i], type=types[i], depth=depth[i], norm_layer=norm_layer, act_layer=act_layer, **dd))
            prev_chs = embed_dim[i]
            self.feature_info.append(dict(num_chs=prev_chs, reduction=2 ** (i + 4), module=f'stages.{i}'))
        self.stages = nn.Sequential(*stages)
        self.num_features = self.head_hidden_size = embed_dim[-1]
        self.global_pool = SelectAdaptivePool2d(pool_type=global_pool)
        assert self.global_pool.feat_mult() == 1, 'Pooling that changes the pooled width is not supported.'
        self.flatten = nn.Flatten(1) if global_pool else nn.Identity()
        self.head = NormLinear(self.head_hidden_size, num_classes, **dd) if num_classes > 0 else nn.Identity()

    def forward_features(self, x):
        x = self.patch_embed(x)
        x = self.stages(x)
        return x

    def forward_head(self, x, pre_logits=False):
        x = self.global_pool(x)
        x = self.flatten(x)
        if self.drop_rate > 0.0:
            x = F.dropout(x, p=self.drop_rate, training=self.training)
        return x if pre_logits else self.head(x)

    def forward(self, x):
        x = self.forward_features(x)
        x = self.forward_head(x)
        return x

    @torch.no_grad()
    def fuse(self):

        def fuse_children(net):
            for child_name, child in net.named_children():
                if hasattr(child, 'fuse'):
                    fused = child.fuse()
                    setattr(net, child_name, fused)
                    fuse_children(fused)
                else:
                    fuse_children(child)
        fuse_children(self)
        return self

def checkpoint_filter_fn(state_dict, model):
    state_dict = state_dict.get('model', state_dict)
