def deepseek_vit_412m_align(pretrained=False, **kwargs):
    model_args = dict(encoder_pool='align')
    return _create_deepseek_vit_classifier('deepseek_vit_412m_align', pretrained=pretrained, **dict(model_args, **kwargs))
