from typing import Callable, List, Optional
import torch
import torch.nn as nn
import torch.nn.functional as F
from torch import Tensor
from collections import OrderedDict

class ConvLayer(nn.Module):

    def __init__(self, in_channels, out_channels, **kwargs):
        super().__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, bias=False, **kwargs)
        self.bn = nn.BatchNorm2d(out_channels, eps=0.001)

    def forward(self, x):
        x = self.conv(x)
        x = self.bn(x)
        return F.relu6(x, inplace=True)

class InvertedResidual(nn.Module):

    def __init__(self, inp, oup, stride, expand_ratio, norm_layer=None):
        super().__init__()
        self.stride = stride
        if norm_layer is None:
            norm_layer = nn.BatchNorm2d
        hidden_dim = int(round(inp * expand_ratio))
        self.use_residual = self.stride == 1 and inp == oup
        layers = []
        if expand_ratio != 1:
            layers.append(ConvLayer(inp, hidden_dim, kernel_size=1))
        layers.append(ConvLayer(hidden_dim, hidden_dim, kernel_size=3, stride=stride, padding=1, groups=hidden_dim))
        layers.append(nn.Conv2d(hidden_dim, oup, 1, 1, 0, bias=False))
        layers.append(norm_layer(oup))
        self.conv = nn.Sequential(*layers)

    def forward(self, x):
        if self.use_residual:
            return x + self.conv(x)
        return self.conv(x)

class ConvNet(nn.Module):

    def __init__(self, stage_cfg, in_chans=3, num_classes=1000, drop_rate=0.0, norm_layer=None, output_stride=32, **kwargs):
        super().__init__()
        assert output_stride in (8, 16, 32)
        if norm_layer is None:
            norm_layer = nn.BatchNorm2d
        self.num_classes = num_classes
        self.stem = ConvLayer(in_chans, 16, kernel_size=3, stride=2, padding=1)
        in_ch = 16
        self.stage1, in_ch = self._make_layer(*stage_cfg[0], in_ch)
        self.stage2, in_ch = self._make_layer(*stage_cfg[1], in_ch)
        self.stage3, in_ch = self._make_layer(*stage_cfg[2], in_ch)
        self.stage4, in_ch = self._make_layer(*stage_cfg[3], in_ch)
        self.stage5, in_ch = self._make_layer(*stage_cfg[4], in_ch)
        self.global_pool = nn.AdaptiveAvgPool2d((1, 1))
        self.classifier = nn.Sequential(OrderedDict([('flatten', nn.Flatten(1)), ('drop', nn.Dropout(p=drop_rate)), ('fc', nn.Linear(in_ch, num_classes))]))

    def forward(self, x):
        x = self.stem(x)
        x = self.stage1(x)
        x = self.stage2(x)
        x = self.stage3(x)
        x = self.stage4(x)
        x = self.stage5(x)
        x = self.global_pool(x)
        return self.classifier(x)

    @staticmethod
    def _make_layer(t, c, n, stride, se, in_ch):
        blocks = []
        out_c = c
        for i in range(n):
            blocks.append(InvertedResidual(in_ch, out_c, stride if i == 0 else 1, t))
            in_ch = out_c
        return (nn.Sequential(*blocks), in_ch)

def make_model(variant='small', **kwargs):
    cfgs = {'small': [(1, 16, 3, 1, False), (4, 24, 2, 2, False), (3, 32, 2, 2, False), (3, 40, 2, 2, False), (4, 48, 3, 2, True)], 'base': [(1, 16, 4, 1, False), (4, 24, 3, 2, False), (3, 32, 3, 2, False), (3, 40, 3, 2, False), (4, 48, 4, 2, True)]}
    return ConvNet(cfgs[variant], **kwargs)
