from typing import Callable, List, Optional
import torch
import torch.nn as nn
import torch.nn.functional as F
from torch import Tensor

def build_layers(cfg, batch_norm=False):
    layers = []
    in_channels = 3
    for v in cfg:
        if v == 'M':
            layers += [nn.MaxPool2d(kernel_size=2, stride=2)]
        else:
            conv2d = nn.Conv2d(in_channels, v, kernel_size=3, padding=1)
            if batch_norm:
                layers += [conv2d, nn.BatchNorm2d(v), nn.ReLU(inplace=True)]
            else:
                layers += [conv2d, nn.ReLU(inplace=True)]
            in_channels = v
    return nn.Sequential(*layers)

class VGG(nn.Module):

    def __init__(self, features, num_classes=10, init_weights=True, dropout=0.5):
        super().__init__()
        self.features = features
        self.avgpool = nn.AdaptiveAvgPool2d((2, 2))
        self.classifier = nn.Sequential(nn.Linear(32 * 2 * 2, 64), nn.ReLU(True), nn.Dropout(p=dropout), nn.Linear(64, 64), nn.ReLU(True), nn.Dropout(p=dropout), nn.Linear(64, num_classes))

    def forward(self, input):
        input = self.features(input)
        input = self.avgpool(input)
        input = torch.flatten(input, 1)
        input = self.classifier(input)
        return input
cfgs = {'A': [8, 8, 'M', 16, 16, 'M', 32, 'M'], 'B': [8, 8, 'M', 16, 16, 16, 'M', 32, 'M']}

def _vgg(cfg, batch_norm, **kwargs):
    return VGG(build_layers(cfgs[cfg], batch_norm=batch_norm), **kwargs)

def vgg_a(**kwargs):
    return _vgg('A', True, **kwargs)
