class Attention(nn.Module):

    def __init__(self, dim, key_dim, num_heads=8, attn_ratio=4.0, resolution=14, use_conv=False, act_layer=nn.SiLU, device=None, dtype=None):
        dd = {'device': device, 'dtype': dtype}
        super().__init__()
        ln_layer = ConvNorm if use_conv else LinearNorm
        resolution = to_2tuple(resolution)
        self.use_conv = use_conv
        self.num_heads = num_heads
        self.scale = key_dim ** (-0.5)
        self.key_dim = key_dim
        self.key_attn_dim = key_dim * num_heads
        self.val_dim = int(attn_ratio * key_dim)
        self.val_attn_dim = int(attn_ratio * key_dim) * num_heads
        self.resolution = resolution
        self.qkv = ln_layer(dim, self.val_attn_dim + self.key_attn_dim * 2, **dd)
        self.proj = nn.Sequential(OrderedDict([('act', act_layer()), ('ln', ln_layer(self.val_attn_dim, dim, bn_weight_init=0, **dd))]))
        N = resolution[0] * resolution[1]
        self.attention_biases = nn.Parameter(torch.empty(num_heads, N, **dd))
        self.register_buffer('attention_bias_idxs', torch.empty((N, N), device=device, dtype=torch.long), persistent=False)
        self.attention_bias_cache = {}
        self.reset_parameters()

    @torch.no_grad()
    def train(self, mode=True):
        super().train(mode)
        if self.attention_bias_cache:
            self.attention_bias_cache = {}

    def _apply(self, fn, *args, **kwargs):
        self.attention_bias_cache = {}
        return super()._apply(fn, *args, **kwargs)

    def reset_parameters(self):
        self._init_buffers()

    def _compute_attention_bias_idxs(self, device=None):
        pos = torch.stack(ndgrid(torch.arange(self.resolution[0], device=device, dtype=torch.long), torch.arange(self.resolution[1], device=device, dtype=torch.long))).flatten(1)
        rel_pos = (pos[..., :, None] - pos[..., None, :]).abs()
        rel_pos = rel_pos[0] * self.resolution[1] + rel_pos[1]
        return rel_pos

    def _init_buffers(self):
        self.attention_bias_idxs.copy_(self._compute_attention_bias_idxs(device=self.attention_bias_idxs.device))
        self.attention_bias_cache = {}

    def get_attention_biases(self, device):
        if torch.jit.is_tracing() or self.training:
            return self.attention_biases[:, self.attention_bias_idxs]
        else:
            device_key = str(device)
            if device_key not in self.attention_bias_cache:
                self.attention_bias_cache[device_key] = self.attention_biases[:, self.attention_bias_idxs]
            return self.attention_bias_cache[device_key]

    def forward(self, x):
        if self.use_conv:
            B, C, H, W = x.shape
            q, k, v = self.qkv(x).view(B, self.num_heads, -1, H * W).split([self.key_dim, self.key_dim, self.val_dim], dim=2)
            attn = q.transpose(-2, -1) @ k * self.scale + self.get_attention_biases(x.device)
            attn = attn.softmax(dim=-1)
            x = (v @ attn.transpose(-2, -1)).view(B, -1, H, W)
        else:
            B, N, C = x.shape
            q, k, v = self.qkv(x).view(B, N, self.num_heads, -1).split([self.key_dim, self.key_dim, self.val_dim], dim=3)
            q = q.permute(0, 2, 1, 3)
            k = k.permute(0, 2, 3, 1)
            v = v.permute(0, 2, 1, 3)
            attn = q @ k * self.scale + self.get_attention_biases(x.device)
            attn = attn.softmax(dim=-1)
            x = (attn @ v).transpose(1, 2).reshape(B, N, self.val_attn_dim)
        x = self.proj(x)
        return x
