from typing import Any, Callable, List, Optional
import torch
from torch import Tensor, nn
import torch.nn.functional as F

def make_conv(in_channels, out_channels, kernel_size=3, stride=1, groups=1, act=True):
    padding = (kernel_size - 1) // 2 if isinstance(kernel_size, int) else tuple(((k - 1) // 2 for k in kernel_size))
    layers = [nn.Conv2d(in_channels, out_channels, kernel_size, stride=stride, padding=padding, groups=groups, bias=False), nn.BatchNorm2d(out_channels)]
    if act:
        layers.append(nn.SiLU())
    return nn.Sequential(*layers)

class InvertedBottleneck(nn.Module):

    def __init__(self, inp, oup, stride, expand_ratio, norm_layer=None):
        super().__init__()
        self.stride = stride
        if norm_layer is None:
            norm_layer = nn.BatchNorm2d
        hidden_dim = int(round(inp * expand_ratio))
        self.use_res_connect = self.stride == 1 and inp == oup
        layers = []
        if expand_ratio != 1:
            layers.append(make_conv(inp, hidden_dim, kernel_size=1))
        layers.append(make_conv(hidden_dim, hidden_dim, kernel_size=3, stride=stride, groups=hidden_dim))
        layers.append(nn.Conv2d(hidden_dim, oup, 1, 1, 0, bias=False))
        layers.append(norm_layer(oup))
        self.conv = nn.Sequential(*layers)

    def forward(self, input):
        if self.use_res_connect:
            return input + self.conv(input)
        return self.conv(input)

def _make_divisible(v, divisor=8, min_value=None):
    if min_value is None:
        min_value = divisor
    new_v = max(min_value, int(v + divisor / 2) // divisor * divisor)
    if new_v < 0.9 * v:
        new_v += divisor
    return new_v

class NormMlpHead(nn.Module):

    def __init__(self, in_features, num_classes, drop_rate=0.0):
        super().__init__()
        self.global_pool = nn.AdaptiveAvgPool2d(1)
        self.flatten = nn.Flatten(1)
        self.drop = nn.Dropout(drop_rate)
        self.fc = nn.Linear(in_features, num_classes) if num_classes > 0 else nn.Identity()

    def forward(self, x, pre_logits=False):
        x = self.global_pool(x)
        x = self.flatten(x)
        x = self.drop(x)
        return x if pre_logits else self.fc(x)

class Net(nn.Module):

    def __init__(self, settings, in_chans=3, num_classes=1000, drop_rate=0.0, width_mult=1.0, norm_layer=None, output_stride=32):
        super().__init__()
        assert output_stride in (8, 16, 32)
        if norm_layer is None:
            norm_layer = nn.BatchNorm2d
        self.num_classes = num_classes
        self.stem = make_conv(in_chans, 16, kernel_size=3, stride=2)
        in_ch = 16
        self.width_mult = width_mult
        self.layer1, in_ch = self._make_layer(*settings[0], in_ch)
        self.layer2, in_ch = self._make_layer(*settings[1], in_ch)
        self.layer3, in_ch = self._make_layer(*settings[2], in_ch)
        self.layer4, in_ch = self._make_layer(*settings[3], in_ch)
        self.head = NormMlpHead(in_ch, num_classes, drop_rate=drop_rate)

    def forward_features(self, input):
        input = self.stem(input)
        input = self.layer1(input)
        input = self.layer2(input)
        input = self.layer3(input)
        input = self.layer4(input)
        return input

    def forward_head(self, input, pre_logits=False):
        return self.head(input, pre_logits=pre_logits)

    def forward(self, input):
        input = self.forward_features(input)
        input = self.forward_head(input)
        return input

    def _make_layer(self, t, c, n, stride, se, in_ch):
        blocks = []
        out_c = _make_divisible(c * self.width_mult, 8)
        for i in range(n):
            blocks.append(InvertedBottleneck(in_ch, out_c, stride if i == 0 else 1, t))
            in_ch = out_c
        return (nn.Sequential(*blocks), in_ch)

def _net(variant, weights=None, progress=True, **kwargs):
    cfgs = {'small': [(1, 16, 2, 1, False), (3, 24, 3, 2, True), (4, 32, 1, 2, True), (6, 40, 1, 2, False)], 'base': [(1, 16, 3, 1, False), (3, 24, 4, 2, True), (4, 32, 2, 2, True), (6, 40, 2, 2, False)]}
    model = Net(cfgs[variant], **kwargs)
    if weights is not None:
        model.load_state_dict(weights.get_state_dict(progress=progress))
    return model

def build_model(weights=None, progress=True, **kwargs):
    return _net('base', weights, progress, **kwargs)
