from typing import Any, Callable, List, Optional
import torch
from torch import Tensor, nn
import torch.nn.functional as F
from functools import partial

class FireModule(nn.Module):

    def __init__(self, inplanes, squeeze_planes, expand1x1_planes, expand3x3_planes):
        super(FireModule, self).__init__()
        self.inplanes = inplanes
        self.sq = nn.Conv2d(inplanes, squeeze_planes, kernel_size=1)
        self.ex1 = nn.Conv2d(squeeze_planes, expand1x1_planes, kernel_size=1)
        self.ex3 = nn.Conv2d(squeeze_planes, expand3x3_planes, kernel_size=3, padding=1)

    def forward(self, inp):
        inp = F.hardswish(self.sq(inp))
        return torch.cat([F.hardswish(self.ex1(inp)), F.hardswish(self.ex3(inp))], 1)

def round_width(width, group_width):
    group_width = min(group_width, width)
    return int(round(width / group_width) * group_width)

class ResBottleneckBlock(nn.Module):

    def __init__(self, in_ch, out_ch, stride, group_width, bottleneck_ratio=1.0, se_ratio=None):
        super(ResBottleneckBlock, self).__init__()
        w_b = int(round(out_ch * bottleneck_ratio))
        groups = w_b // group_width
        self.f_a = nn.Sequential(nn.Conv2d(in_ch, w_b, 1, bias=False), nn.BatchNorm2d(w_b), nn.Hardswish())
        self.f_b = nn.Sequential(nn.Conv2d(w_b, w_b, 3, stride=stride, padding=1, groups=groups, bias=False), nn.BatchNorm2d(w_b), nn.Hardswish())
        self.se = None
        self.f_c = nn.Sequential(nn.Conv2d(w_b, out_ch, 1, bias=False), nn.BatchNorm2d(out_ch))
        self.downsample = None
        if in_ch != out_ch or stride != 1:
            self.downsample = nn.Sequential(nn.Conv2d(in_ch, out_ch, 1, stride=stride, bias=False), nn.BatchNorm2d(out_ch))
        self.act = nn.Hardswish()

    def forward(self, inp):
        shortcut = inp if self.downsample is None else self.downsample(inp)
        inp = self.f_a(inp)
        inp = self.f_b(inp)
        if self.se is not None:
            inp = self.se(inp)
        inp = self.f_c(inp)
        return self.act(inp + shortcut)

class ConvBNActivation(nn.Sequential):

    def __init__(self, in_channels, out_channels, kernel_size=3, stride=1, groups=1, act=True):
        padding = (kernel_size - 1) // 2 if isinstance(kernel_size, int) else tuple(((k - 1) // 2 for k in kernel_size))
        layers = [nn.Conv2d(in_channels, out_channels, kernel_size, stride, padding, groups=groups, bias=False), nn.BatchNorm2d(out_channels)]
        if act:
            layers.append(nn.Hardswish())
        super(ConvBNActivation, self).__init__(*layers)

class Net(nn.Module):

    def __init__(self, stem_stages, main_stages, in_chans=3, num_classes=100, drop_rate=0.0, norm_layer=None, output_stride=32, **kwargs):
        super(Net, self).__init__()
        assert output_stride in (8, 16, 32)
        if norm_layer is None:
            norm_layer = partial(nn.BatchNorm2d, eps=0.001)
        self.num_classes = num_classes
        self.stem = ConvBNActivation(in_chans, 16, kernel_size=3, stride=2)
        in_ch = 16
        self.feature_info = []
        for idx, (sq, e, n) in enumerate(stem_stages):
            blocks = []
            if idx > 0:
                blocks.append(nn.MaxPool2d(kernel_size=3, stride=2, ceil_mode=True))
            for _ in range(n):
                blocks.append(FireModule(in_ch, sq, e, e))
                in_ch = 2 * e
            self.add_module(f'layer{idx + 1}', nn.Sequential(*blocks))
            self.feature_info.append(dict(num_chs=in_ch, module=f'layer{idx + 1}'))
        for idx, (w, d, g) in enumerate(main_stages, start=len(stem_stages)):
            blocks = []
            w = round_width(w, g)
            for i in range(d):
                blocks.append(ResBottleneckBlock(in_ch, w, 2 if i == 0 else 1, g))
                in_ch = w
            self.add_module(f'layer{idx + 1}', nn.Sequential(*blocks))
            self.feature_info.append(dict(num_chs=in_ch, module=f'layer{idx + 1}'))
        self.num_stages = len(stem_stages) + len(main_stages)
        self.num_features = in_ch
        self.global_pool = nn.AdaptiveAvgPool2d((1, 1))
        self.drop = nn.Identity()
        self.fc = nn.Linear(in_ch, num_classes)

    def forward_features(self, inp):
        inp = self.stem(inp)
        for i in range(self.num_stages):
            inp = getattr(self, f'layer{i + 1}')(inp)
        return inp

    def forward_head(self, inp, pre_logits=False):
        inp = self.global_pool(inp)
        inp = inp.flatten(1)
        inp = self.drop(inp)
        return inp if pre_logits else self.fc(inp)

    def forward(self, inp):
        inp = self.forward_features(inp)
        inp = self.forward_head(inp)
        return inp

def make_model(variant='small', **kwargs):
    cfgs = {'small': ([(8, 32, 3), (16, 64, 1)], [(48, 3, 16)])}
    return Net(*cfgs[variant], **kwargs)
