        self.bn = nn.BatchNorm2d(out_chs, **dd)

    def forward(self, x):
        return self.bn(self.linear(x))

class LinearNorm(nn.Module):

    def __init__(self, in_features, out_features, bn_weight_init=1, device=None, dtype=None):
