    def __init__(self, dim, key_dim, num_heads=8, attn_ratio=4.0, mlp_ratio=2.0, resolution=14, use_conv=False, act_layer=nn.SiLU, attn_act_layer=None, drop_path=0.0, device=None, dtype=None):
