    def __init__(self, in_dim, dim, depth, num_attn, hdrr, conv_ratio, ffn_ratio, attn_ratio, drop_path_rates, layer_scale_init_value, act_layer, device=None, dtype=None):
        dd = {'device': device, 'dtype': dtype}
        super().__init__()
        assert depth >= 3 * num_attn, 'Each attention group requires three blocks.'
        self.grad_checkpointing = False
        self.downsample = nn.Identity() if in_dim == dim else ConvNorm(in_dim, dim, 3, 2, 1, **dd)
        blocks = []
        if num_attn == 0:
            for j in range(depth):
                blocks.append(ConvBlock(dim, 7, conv_ratio, drop_path_rates[j], layer_scale_init_value, act_layer, **dd))
        else:
            num_conv = depth - num_attn * 3
            num_prefix, num_suffix = (num_conv - 1, 1) if num_conv > 0 else (0, 0)
            for j in range(num_prefix):
                blocks.append(ConvBlock(dim, 7, conv_ratio, drop_path_rates[j], layer_scale_init_value, act_layer, **dd))
            for g in range(num_attn):
                offset = num_prefix + g * 3
                blocks.append(RepCPE(dim, 3, **dd))
                blocks.append(SHMABlock(dim, attn_ratio, hdrr, drop_path_rates[offset + 1], layer_scale_init_value, **dd))
                blocks.append(FFN(dim, ffn_ratio, drop_path_rates[offset + 2], layer_scale_init_value, act_layer, **dd))
            if num_suffix:
                blocks.append(ConvBlock(dim, 7, conv_ratio, drop_path_rates[-1], layer_scale_init_value, act_layer, **dd))
        self.blocks = nn.Sequential(*blocks)

    def forward(self, x):
        x = self.downsample(x)
        if self.grad_checkpointing and (not torch.jit.is_scripting()):
            x = checkpoint_seq(self.blocks, x)
        else:
            x = self.blocks(x)
        return x
