class Residual(nn.Module):

    def __init__(self, module, drop_path=0.0, layer_scale_init_value=0, dim=None, device=None, dtype=None):
        dd = {'device': device, 'dtype': dtype}
        super().__init__()
        self.module = module
        self.layer_scale_init_value = layer_scale_init_value
        self.drop_path = DropPath(drop_path) if drop_path > 0.0 else nn.Identity()
        if layer_scale_init_value > 0 and dim is not None:
            self.gamma = nn.Parameter(layer_scale_init_value * torch.ones((1, dim, 1, 1), **dd), requires_grad=True)
        else:
            self.gamma = None

    def forward(self, x):
        if self.gamma is not None:
            return x + self.gamma * self.drop_path(self.module(x))
        return x + self.drop_path(self.module(x))
