from typing import Any, Callable, List, Optional
import torch
from torch import Tensor, nn
import torch.nn.functional as F
from collections import OrderedDict
from functools import partial

def conv3x3(in_planes, out_planes, stride=1, groups=1):
    return nn.Conv2d(in_planes, out_planes, kernel_size=3, stride=stride, padding=1, groups=groups, bias=False)

def conv1x1(in_planes, out_planes, stride=1):
    return nn.Conv2d(in_planes, out_planes, kernel_size=1, stride=stride, bias=False)

class BasicBlock(nn.Module):
    expansion = 1

    def __init__(self, inplanes, planes, stride=1, skip=None, norm_layer=None):
        super(BasicBlock, self).__init__()
        if norm_layer is None:
            norm_layer = nn.BatchNorm2d
        self.conv_a = conv3x3(inplanes, planes, stride)
        self.norm1 = norm_layer(planes)
        self.conv_b = conv3x3(planes, planes)
        self.norm2 = norm_layer(planes)
        self.skip = skip
        self.stride = stride

    def forward(self, feats):
        identity = feats
        h = self.conv_a(feats)
        h = self.norm1(h)
        h = F.hardswish(h)
        h = self.conv_b(h)
        h = self.norm2(h)
        if self.skip is not None:
            identity = self.skip(feats)
        h = h + identity
        h = F.hardswish(h)
        return h

class Stage(nn.Module):

    def __init__(self, planes, n, stride, in_ch, norm_layer=None):
        super(Stage, self).__init__()
        if norm_layer is None:
            norm_layer = nn.BatchNorm2d
        blocks = []
        downsample = None
        if stride != 1 or in_ch != planes * BasicBlock.expansion:
            downsample = nn.Sequential(conv1x1(in_ch, planes * BasicBlock.expansion, stride), norm_layer(planes * BasicBlock.expansion))
        blocks.append(BasicBlock(in_ch, planes, stride, downsample))
        in_ch = planes * BasicBlock.expansion
        for _ in range(1, n):
            blocks.append(BasicBlock(in_ch, planes))
        self.blocks = nn.Sequential(*blocks)
        self.out_channels = in_ch

    def forward(self, x):
        return self.blocks(x)

class Network(nn.Module):

    def __init__(self, stage_cfg, in_chans=3, num_classes=100, drop_rate=0.0, norm_layer=None, output_stride=32):
        super(Network, self).__init__()
        assert output_stride in (8, 16, 32)
        if norm_layer is None:
            norm_layer = partial(nn.BatchNorm2d, eps=1e-05)
        self.num_classes = num_classes
        self.stem = nn.Sequential(OrderedDict([('conv', nn.Conv2d(in_chans, 16, kernel_size=3, stride=2, padding=1, bias=False)), ('bn', norm_layer(16)), ('act', nn.Hardswish())]))
        in_ch = 16
        stages = []
        for idx, (planes, n, stride) in enumerate(stage_cfg):
            stage = Stage(planes, n, stride, in_ch)
            stages.append(stage)
            in_ch = stage.out_channels
        self.stages = nn.Sequential(*stages)
        self.global_pool = nn.AdaptiveAvgPool2d(1)
        self.classifier = nn.Sequential(OrderedDict([('flatten', nn.Flatten(1)), ('drop', nn.Dropout(p=drop_rate)), ('fc', nn.Linear(in_ch, num_classes))]))

    def forward(self, feats):
        torch._assert(feats.dim() == 4, f'expected a 4D input, got {feats.dim()}D')
        feats = self.stem(feats)
        feats = self.stages(feats)
        feats = self.global_pool(feats)
        return self.classifier(feats)

def _network(variant, weights=None, progress=True, **kwargs):
    cfgs = {'small': [(8, 1, 1), (16, 3, 2), (32, 2, 2), (64, 2, 2)], 'base': [(8, 2, 1), (16, 4, 2), (32, 3, 2), (64, 3, 2)]}
    model = Network(cfgs[variant], **kwargs)
    if weights is not None:
        model.load_state_dict(weights.get_state_dict(progress=progress))
    return model

def create_net(weights=None, progress=True, **kwargs):
    return _network('base', weights, progress, **kwargs)
