def rdnet_small(pretrained=False, **kwargs):
    n_layer = 11
    model_args = {'num_init_features': 72, 'growth_rates': [64] + [128] + [128] * (n_layer - 4) + [240] * 2, 'num_blocks_list': [3] * n_layer, 'is_downsample_block': (None, True, True, False, False, False, False, False, False, True, False), 'transition_compression_ratio': 0.5, 'block_type': ['Block'] + ['Block'] + ['BlockESE'] * (n_layer - 4) + ['BlockESE'] * 2}
    model = _create_rdnet('rdnet_small', pretrained=pretrained, **dict(model_args, **kwargs))
    return model
