import torch
import torch.nn as nn
import torch.nn.functional as F
from functools import partial

def make_conv(in_channels, out_channels, kernel_size=3, stride=1, groups=1, act=True):
    padding = (kernel_size - 1) // 2 if isinstance(kernel_size, int) else tuple(((k - 1) // 2 for k in kernel_size))
    layers = [nn.Conv2d(in_channels, out_channels, kernel_size, stride=stride, padding=padding, groups=groups, bias=False), nn.BatchNorm2d(out_channels)]
    if act:
        layers.append(nn.ReLU6())
    return nn.Sequential(*layers)

class InvertedResidual(nn.Module):

    def __init__(self, inp, oup, stride, expand_ratio, norm_layer=None):
        super(InvertedResidual, self).__init__()
        self.stride = stride
        if norm_layer is None:
            norm_layer = nn.BatchNorm2d
        hidden_dim = int(round(inp * expand_ratio))
        self.use_residual = self.stride == 1 and inp == oup
        layers = []
        if expand_ratio != 1:
            layers.append(make_conv(inp, hidden_dim, kernel_size=1))
        layers.append(make_conv(hidden_dim, hidden_dim, kernel_size=3, stride=stride, groups=hidden_dim))
        layers.append(nn.Conv2d(hidden_dim, oup, 1, 1, 0, bias=False))
        layers.append(norm_layer(oup))
        self.conv = nn.Sequential(*layers)

    def forward(self, z):
        if self.use_residual:
            return z + self.conv(z)
        return self.conv(z)

def _make_divisible(v, divisor=8, min_value=None):
    if min_value is None:
        min_value = divisor
    new_v = max(min_value, int(v + divisor / 2) // divisor * divisor)
    if new_v < 0.9 * v:
        new_v += divisor
    return new_v

class Net(nn.Module):

    def __init__(self, arch, in_chans=3, num_classes=10, drop_rate=0.0, width_mult=1.0, norm_layer=None, **kwargs):
        super(Net, self).__init__()
        if norm_layer is None:
            norm_layer = partial(nn.BatchNorm2d, eps=1e-05)
        self.num_classes = num_classes
        self.stem = make_conv(in_chans, 8, kernel_size=3, stride=2)
        in_ch = 8
        for idx, (t, c, n, stride, se) in enumerate(arch):
            blocks = []
            out_c = _make_divisible(c * width_mult, 8)
            for i in range(n):
                blocks.append(InvertedResidual(in_ch, out_c, stride if i == 0 else 1, t))
                in_ch = out_c
            self.add_module(f'layer{idx + 1}', nn.Sequential(*blocks))
        self.num_stages = len(arch)
        self.drop = nn.Dropout(drop_rate)
        self.fc = nn.Linear(in_ch, num_classes)

    def forward_features(self, z):
        z = self.stem(z)
        for i in range(self.num_stages):
            z = getattr(self, f'layer{i + 1}')(z)
        return z

    def forward_head(self, z, pre_logits=False):
        z = z.mean((2, 3), keepdim=True)
        z = z.flatten(1)
        z = self.drop(z)
        return z if pre_logits else self.fc(z)

    def forward(self, z):
        z = self.forward_features(z)
        z = self.forward_head(z)
        return z
ARCH = [(1, 16, 2, 1, True), (4, 24, 3, 2, True), (3, 32, 2, 2, False), (6, 40, 1, 2, False)]
model = Net(ARCH)
example_input = torch.randn(1, 3, 64, 64)
