    def __init__(self, dim, num_heads, qkv_bias=True, qkv_fused=True, mlp_ratio=4.0, swiglu_mlp=False, swiglu_align_to=0, scale_mlp=False, scale_attn_inner=False, num_prefix_tokens=1, attn_type='eva', rotate_half=False, gated_attn=False, qk_norm=False, num_kv_heads=None, proj_drop=0.0, attn_drop=0.0, drop_path=0.0, init_values=None, attn_only_layer_scale=False, act_layer=nn.GELU, norm_layer=LayerNorm, attn_head_dim=None, device=None, dtype=None, **kwargs):
