        self.attn = attn_cls(dim, num_heads=num_heads, qkv_bias=qkv_bias, qkv_fused=qkv_fused, num_prefix_tokens=num_prefix_tokens, attn_drop=attn_drop, proj_drop=proj_drop, attn_head_dim=attn_head_dim, norm_layer=norm_layer, qk_norm=qk_norm, scale_norm=scale_attn_inner, rotate_half=rotate_half, gated=gated_attn, **attn_kwargs, **dd)
