        if self.gamma_1 is not None:
            x_attn = self.gamma_1 * x_attn
        x = x + self.drop_path1(x_attn)
        x_mlp = self.mlp(self.norm2(x))
        if self.gamma_2 is not None:
            x_mlp = self.gamma_2 * x_mlp
        x = x + self.drop_path2(x_mlp)
        return x

class EvaBlockPostNorm(nn.Module):

    def __init__(self, dim, num_heads, qkv_bias=True, qkv_fused=True, mlp_ratio=4.0, attn_type='eva', rotate_half=False, gated_attn=False, swiglu_mlp=False, swiglu_align_to=0, scale_mlp=False, scale_attn_inner=False, num_prefix_tokens=1, proj_drop=0.0, attn_drop=0.0, drop_path=0.0, init_values=None, act_layer=nn.GELU, norm_layer=nn.LayerNorm, attn_head_dim=None, device=None, dtype=None, **kwargs):
