class Eva(nn.Module):

    def __init__(self, img_size=224, patch_size=16, in_chans=3, num_classes=1000, global_pool='avg', embed_dim=768, depth=12, num_heads=12, num_kv_heads=None, qkv_bias=True, qkv_fused=True, qk_norm=False, mlp_ratio=4.0, swiglu_mlp=False, swiglu_align_to=0, scale_mlp=False, scale_attn_inner=False, attn_type='eva', drop_rate=0.0, pos_drop_rate=0.0, patch_drop_rate=0.0, proj_drop_rate=0.0, attn_drop_rate=0.0, drop_path_rate=0.0, norm_layer=LayerNorm, init_values=None, attn_only_layer_scale=False, class_token=True, num_reg_tokens=0, no_embed_class=False, use_abs_pos_emb=True, use_rot_pos_emb=False, rope_type='cat', rope_grid_offset=0.0, rope_grid_indexing='ij', rope_temperature=10000.0, rope_rotate_half=False, rope_shift_coords=None, rope_jitter_coords=None, rope_rescale_coords=None, rope_mrope_section=None, use_post_norm=False, use_pre_transformer_norm=False, use_post_transformer_norm=None, use_fc_norm=None, attn_pool_num_heads=None, attn_pool_mlp_ratio=None, dynamic_img_size=False, dynamic_img_pad=False, ref_feat_shape=None, head_init_scale=0.001, device=None, dtype=None):
