            rope_kwargs = dict(dim=embed_dim, num_heads=num_heads, feat_shape=None if dynamic_img_size else self.patch_embed.grid_size, temperature=rope_temperature, grid_indexing=rope_grid_indexing, rotate_half=rope_rotate_half or rope_type == 'mrope', shift_coords=rope_shift_coords, jitter_coords=rope_jitter_coords, rescale_coords=rope_rescale_coords, **dd)
