        if self.patch_drop is not None:
            x, keep_indices = self.patch_drop(x)
            if rot_pos_embed is not None and keep_indices is not None:
                rot_pos_embed = apply_keep_indices_nlc(x, rot_pos_embed, keep_indices)
                if getattr(self, 'rope_mixed', False):
                    rot_pos_embed = rot_pos_embed.transpose(0, 1)
                else:
                    rot_pos_embed = rot_pos_embed.unsqueeze(1)
        return (x, rot_pos_embed)

    def pool(self, x, pool_type=None):
        if self.attn_pool is not None:
            x = self.attn_pool(x)
            return x
        pool_type = self.global_pool if pool_type is None else pool_type
        x = global_pool_nlc(x, pool_type=pool_type, num_prefix_tokens=self.num_prefix_tokens)
        return x

    def forward_features(self, x, attn_mask=None, is_causal=False):
        x = self.patch_embed(x)
        x, rot_pos_embed = self._pos_embed(x)
        x = self.norm_pre(x)
        if getattr(self, 'rope_mixed', False) and rot_pos_embed is not None:
            for i, blk in enumerate(self.blocks):
                if self.grad_checkpointing and (not torch.jit.is_scripting()):
                    x = checkpoint(blk, x, rope=rot_pos_embed[i], attn_mask=attn_mask, is_causal=is_causal)
                else:
                    x = blk(x, rope=rot_pos_embed[i], attn_mask=attn_mask, is_causal=is_causal)
        else:
            for blk in self.blocks:
                if self.grad_checkpointing and (not torch.jit.is_scripting()):
                    x = checkpoint(blk, x, rope=rot_pos_embed, attn_mask=attn_mask, is_causal=is_causal)
                else:
                    x = blk(x, rope=rot_pos_embed, attn_mask=attn_mask, is_causal=is_causal)
        x = self.norm(x)
        return x

    def forward_head(self, x, pre_logits=False):
        x = self.pool(x)
        x = self.fc_norm(x)
        x = self.head_drop(x)
        return x if pre_logits else self.head(x)

    def forward(self, x, attn_mask=None, is_causal=False):
        x = self.forward_features(x, attn_mask=attn_mask, is_causal=is_causal)
        x = self.forward_head(x)
        return x

def _convert_pe(state_dict, model, prefix='visual.'):
    state_dict = state_dict.get('model', state_dict)
    state_dict = {k.replace('module.', ''): v for k, v in state_dict.items()}
    out_dict = {}
    swaps = [('conv1', 'patch_embed.proj'), ('positional_embedding', 'pos_embed'), ('transformer.resblocks.', 'blocks.'), ('ln_pre', 'norm_pre'), ('ln_post', 'norm'), ('ln_', 'norm'), ('ls_1.gamma', 'gamma_1'), ('ls_2.gamma', 'gamma_2'), ('in_proj_', 'qkv.'), ('out_proj', 'proj'), ('mlp.c_fc', 'mlp.fc1'), ('mlp.c_proj', 'mlp.fc2')]
    len_prefix = len(prefix)
    for k, v in state_dict.items():
        if prefix:
            if not k.startswith(prefix):
                continue
            k = k[len_prefix:]
        for sp in swaps:
            k = k.replace(sp[0], sp[1])
        if k.startswith('attn_pool'):
            k = k.replace('attn_pool.attn', 'attn_pool')
            k = k.replace('attn_pool.layernorm', 'attn_pool.norm')
            k = k.replace('attn_pool.probe', 'attn_pool.latent')
            if k.startswith('attn_pool.qkv'):
                dim = v.shape[0] // 3
                if k.endswith('weight'):
                    out_dict['attn_pool.q.weight'] = v[:dim]
                    out_dict['attn_pool.kv.weight'] = v[dim:]
                elif k.endswith('bias'):
                    out_dict['attn_pool.q.bias'] = v[:dim]
                    out_dict['attn_pool.kv.bias'] = v[dim:]
                continue
        elif k == 'proj':
            k = 'head.weight'
            v = v.transpose(0, 1)
            out_dict['head.bias'] = torch.zeros(v.shape[0])
        elif k == 'class_embedding':
            k = 'cls_token'
            v = v.unsqueeze(0).unsqueeze(1)
        elif k == 'pos_embed':
            v = v.unsqueeze(0)
        out_dict[k] = v
    return out_dict

def checkpoint_filter_fn(state_dict, model, interpolation='bicubic', antialias=True):
    out_dict = {}
    state_dict = state_dict.get('model_ema', state_dict)
    state_dict = state_dict.get('model', state_dict)
    state_dict = state_dict.get('module', state_dict)
    state_dict = state_dict.get('state_dict', state_dict)
    if 'visual.conv1.weight' in state_dict:
        return _convert_pe(state_dict, model)
    elif 'conv1.weight' in state_dict:
        return _convert_pe(state_dict, model, prefix='')
    if 'visual.trunk.pos_embed' in state_dict:
        prefix = 'visual.trunk.'
    elif 'visual.pos_embed' in state_dict:
        prefix = 'visual.'
    else:
        prefix = ''
    sapiens2_weights = 'blocks.0.attn.wq.weight' in state_dict and 'blocks.0.ffn.w12.weight' in state_dict
    dinov3_weights = 'storage_tokens' in state_dict and (not sapiens2_weights)
    mim_weights = not dinov3_weights and prefix + 'mask_token' in state_dict
    no_qkv = prefix + 'blocks.0.attn.q_proj.weight' in state_dict
    len_prefix = len(prefix)
    for k, v in state_dict.items():
        if prefix:
            if not k.startswith(prefix):
                continue
            k = k[len_prefix:]
        if 'rope' in k and (not k == 'rope.freqs'):
            continue
        if sapiens2_weights:
            if k == 'mask_token':
                continue
            k = k.replace('storage_tokens', 'reg_token')
            k = k.replace('patch_embed.projection.', 'patch_embed.proj.')
            k = k.replace('attn.wq.', 'attn.q_proj.')
            k = k.replace('attn.wk.', 'attn.k_proj.')
            k = k.replace('attn.wv.', 'attn.v_proj.')
            k = k.replace('attn.gamma.weight', 'gamma_1')
            k = k.replace('.ffn.', '.mlp.')
            k = k.replace('.ln1.', '.norm1.')
            k = k.replace('.ln2.', '.norm2.')
            if k.startswith('ln1.'):
                k = 'norm.' + k[len('ln1.'):]
        elif dinov3_weights:
            if any([k.endswith(f) for f in ['.periods', '.bias_mask', 'mask_token']]):
                continue
            if k.startswith('projectors.'):
                continue
            if k.startswith('local_cls_norm'):
                continue
            if k.endswith('qkv.bias'):
                q_bias_k = k.replace('qkv.bias', 'q_bias')
                try:
                    model.get_parameter(q_bias_k)
                except Exception as e:
                    print(e)
                    continue
                qv, kv, vv = v.chunk(3, dim=-1)
                out_dict[q_bias_k] = qv
                out_dict[k.replace('qkv.bias', 'v_bias')] = vv
                continue
            k = k.replace('ls1.gamma', 'gamma_1')
            k = k.replace('ls2.gamma', 'gamma_2')
            k = k.replace('storage_tokens', 'reg_token')
        elif mim_weights and k in ('mask_token', 'lm_head.weight', 'lm_head.bias', 'norm.weight', 'norm.bias'):
            if k == 'norm.weight' or k == 'norm.bias':
                k = k.replace('norm', 'fc_norm')
            else:
                continue
        if 'patch_embed.proj.weight' in k:
            _, _, H, W = model.patch_embed.proj.weight.shape
            if v.shape[-1] != W or v.shape[-2] != H:
                v = resample_patch_embed(v, (H, W), interpolation=interpolation, antialias=antialias, verbose=True)
        elif k == 'pos_embed' and model.pos_embed is not None:
            num_prefix_tokens = 0 if getattr(model, 'no_embed_class', False) else getattr(model, 'num_prefix_tokens', 1)
            old_size = get_pretrained_grid_size(model, state_dict.get(prefix + 'patch_embed.proj.weight'), v.shape[1] - num_prefix_tokens)
            if v.shape[1] != model.pos_embed.shape[1] or (old_size is not None and old_size != model.patch_embed.grid_size):
                v = resample_abs_pos_embed(v, new_size=model.patch_embed.grid_size, old_size=old_size, num_prefix_tokens=num_prefix_tokens, interpolation=interpolation, antialias=antialias, verbose=True)
        k = k.replace('mlp.ffn_ln', 'mlp.norm')
        k = k.replace('attn.inner_attn_ln', 'attn.norm')
        k = k.replace('mlp.w12', 'mlp.fc1')
        k = k.replace('mlp.w1', 'mlp.fc1_g')
        k = k.replace('mlp.w2', 'mlp.fc1_x')
        k = k.replace('mlp.w3', 'mlp.fc2')
        if no_qkv:
            k = k.replace('q_bias', 'q_proj.bias')
            k = k.replace('v_bias', 'v_proj.bias')
        out_dict[k] = v
    return out_dict

