from functools import partial
from typing import Any, Dict, List, Optional, Set, Tuple, Type, Union
import torch
import torch.nn as nn
import torch.nn.functional as F
from timm.data import IMAGENET_DEFAULT_MEAN, IMAGENET_DEFAULT_STD
from timm.layers import SelectAdaptivePool2d, Linear, DropPath, trunc_normal_, LayerType, calculate_drop_path_rates, get_device_dtype
from ._builder import build_model_with_cfg
from ._features import feature_take_indices
from ._manipulate import checkpoint_seq
from ._registry import register_model, generate_default_cfgs

class Partial_conv3(nn.Module):

    def __init__(self, dim, n_div, forward, device=None, dtype=None):
        dd = {'device': device, 'dtype': dtype}
        super().__init__()
        self.dim_conv3 = dim // n_div
        self.dim_untouched = dim - self.dim_conv3
        self.partial_conv3 = nn.Conv2d(self.dim_conv3, self.dim_conv3, 3, 1, 1, bias=False, **dd)
        if forward == 'slicing':
            self.forward = self.forward_slicing
        elif forward == 'split_cat':
            self.forward = self.forward_split_cat
        else:
            raise NotImplementedError

    def forward_slicing(self, x):
        x = x.clone()
        x[:, :self.dim_conv3, :, :] = self.partial_conv3(x[:, :self.dim_conv3, :, :])
        return x

    def forward_split_cat(self, x):
        x1, x2 = torch.split(x, [self.dim_conv3, self.dim_untouched], dim=1)
        x1 = self.partial_conv3(x1)
        x = torch.cat((x1, x2), 1)
        return x

class MLPBlock(nn.Module):

    def __init__(self, dim, n_div, mlp_ratio, drop_path, layer_scale_init_value, act_layer=partial(nn.ReLU, inplace=True), norm_layer=nn.BatchNorm2d, pconv_fw_type='split_cat', device=None, dtype=None):
        dd = {'device': device, 'dtype': dtype}
        super().__init__()
        mlp_hidden_dim = int(dim * mlp_ratio)
        self.mlp = nn.Sequential(*[nn.Conv2d(dim, mlp_hidden_dim, 1, bias=False, **dd), norm_layer(mlp_hidden_dim, **dd), act_layer(), nn.Conv2d(mlp_hidden_dim, dim, 1, bias=False, **dd)])
        self.spatial_mixing = Partial_conv3(dim, n_div, pconv_fw_type, **dd)
        if layer_scale_init_value > 0:
            self.layer_scale = nn.Parameter(layer_scale_init_value * torch.ones(dim, **dd), requires_grad=True)
        else:
            self.layer_scale = None
        self.drop_path = DropPath(drop_path) if drop_path > 0.0 else nn.Identity()

    def forward(self, x):
        shortcut = x
        x = self.spatial_mixing(x)
        if self.layer_scale is not None:
            x = shortcut + self.drop_path(self.layer_scale.unsqueeze(-1).unsqueeze(-1) * self.mlp(x))
        else:
            x = shortcut + self.drop_path(self.mlp(x))
        return x

class Block(nn.Module):

    def __init__(self, dim, depth, n_div, mlp_ratio, drop_path, layer_scale_init_value, act_layer=partial(nn.ReLU, inplace=True), norm_layer=nn.BatchNorm2d, pconv_fw_type='split_cat', use_merge=True, merge_size=2, device=None, dtype=None):
        dd = {'device': device, 'dtype': dtype}
        super().__init__()
        self.grad_checkpointing = False
        self.blocks = nn.Sequential(*[MLPBlock(dim=dim, n_div=n_div, mlp_ratio=mlp_ratio, drop_path=drop_path[i], layer_scale_init_value=layer_scale_init_value, norm_layer=norm_layer, act_layer=act_layer, pconv_fw_type=pconv_fw_type, **dd) for i in range(depth)])
        self.downsample = PatchMerging(dim=dim // 2, patch_size=merge_size, norm_layer=norm_layer, **dd) if use_merge else nn.Identity()

    def forward(self, x):
        x = self.downsample(x)
        if self.grad_checkpointing and (not torch.jit.is_scripting()):
            x = checkpoint_seq(self.blocks, x)
        else:
            x = self.blocks(x)
        return x

class PatchEmbed(nn.Module):

    def __init__(self, in_chans, embed_dim, patch_size=4, norm_layer=nn.BatchNorm2d, device=None, dtype=None):
        dd = {'device': device, 'dtype': dtype}
        super().__init__()
        self.proj = nn.Conv2d(in_chans, embed_dim, patch_size, patch_size, bias=False, **dd)
        self.norm = norm_layer(embed_dim, **dd)

    def forward(self, x):
        return self.norm(self.proj(x))

class PatchMerging(nn.Module):

    def __init__(self, dim, patch_size=2, norm_layer=nn.BatchNorm2d, device=None, dtype=None):
        dd = {'device': device, 'dtype': dtype}
        super().__init__()
        self.reduction = nn.Conv2d(dim, 2 * dim, patch_size, patch_size, bias=False, **dd)
        self.norm = norm_layer(2 * dim, **dd)

    def forward(self, x):
        return self.norm(self.reduction(x))

class FasterNet(nn.Module):

    def __init__(self, in_chans=3, num_classes=1000, global_pool='avg', embed_dim=96, depths=(1, 2, 8, 2), mlp_ratio=2.0, n_div=4, patch_size=4, merge_size=2, patch_norm=True, feature_dim=1280, drop_rate=0.0, drop_path_rate=0.1, layer_scale_init_value=0.0, act_layer=partial(nn.ReLU, inplace=True), norm_layer=nn.BatchNorm2d, pconv_fw_type='split_cat', device=None, dtype=None):
        super().__init__()
        dd = {'device': device, 'dtype': dtype}
        assert pconv_fw_type in ('split_cat', 'slicing')
        self.num_classes = num_classes
        self.in_chans = in_chans
        self.drop_rate = drop_rate
        if not isinstance(depths, (list, tuple)):
            depths = depths
        self.num_stages = len(depths)
        self.feature_info = []
        self.patch_embed = PatchEmbed(in_chans=in_chans, embed_dim=embed_dim, patch_size=patch_size, norm_layer=norm_layer if patch_norm else nn.Identity, **dd)
        dpr = calculate_drop_path_rates(drop_path_rate, depths, stagewise=True)
        stages_list = []
        for i in range(self.num_stages):
            dim = int(embed_dim * 2 ** i)
            stage = Block(dim=dim, depth=depths[i], n_div=n_div, mlp_ratio=mlp_ratio, drop_path=dpr[i], layer_scale_init_value=layer_scale_init_value, norm_layer=norm_layer, act_layer=act_layer, pconv_fw_type=pconv_fw_type, use_merge=False if i == 0 else True, merge_size=merge_size, **dd)
            stages_list.append(stage)
            self.feature_info += [dict(num_chs=dim, reduction=2 ** (i + 2), module=f'stages.{i}')]
        self.stages = nn.Sequential(*stages_list)
        self.num_features = prev_chs = int(embed_dim * 2 ** (self.num_stages - 1))
        self.head_hidden_size = out_chs = feature_dim
        self.global_pool = SelectAdaptivePool2d(pool_type=global_pool)
        assert self.global_pool.feat_mult() == 1, 'Pooling that changes the pooled width is not supported.'
        self.conv_head = nn.Conv2d(prev_chs, out_chs, 1, 1, 0, bias=False, **dd)
        self.act = act_layer()
        self.flatten = nn.Flatten(1) if global_pool else nn.Identity()
        self.classifier = Linear(out_chs, num_classes, bias=True, **dd) if num_classes > 0 else nn.Identity()
        self._initialize_weights()

    def _initialize_weights(self):
        pass

    def forward_features(self, x):
        x = self.patch_embed(x)
        x = self.stages(x)
        return x

    def forward_head(self, x, pre_logits=False):
        x = self.global_pool(x)
        x = self.conv_head(x)
        x = self.act(x)
        x = self.flatten(x)
        if self.drop_rate > 0.0:
            x = F.dropout(x, p=self.drop_rate, training=self.training)
        return x if pre_logits else self.classifier(x)

    def forward(self, x):
        x = self.forward_features(x)
        x = self.forward_head(x)
        return x

def checkpoint_filter_fn(state_dict, model):
    return state_dict

def _create_fasternet(variant, pretrained=False, **kwargs):
    model = build_model_with_cfg(FasterNet, variant, pretrained, pretrained_filter_fn=checkpoint_filter_fn, feature_cfg=dict(out_indices=(0, 1, 2, 3), flatten_sequential=True), **kwargs)
    return model

