from typing import Any, Callable, List, Optional
import torch
from torch import Tensor, nn
import torch.nn.functional as F

def make_layers(cfg, batch_norm=False):
    layers = []
    in_channels = 3
    for v in cfg:
        if v == 'M':
            layers += [nn.MaxPool2d(kernel_size=2, stride=2)]
        else:
            conv2d = nn.Conv2d(in_channels, v, kernel_size=3, padding=1)
            if batch_norm:
                layers += [conv2d, nn.BatchNorm2d(v), nn.SiLU(inplace=True)]
            else:
                layers += [conv2d, nn.SiLU(inplace=True)]
            in_channels = v
    return nn.Sequential(*layers)

class PlainNet(nn.Module):

    def __init__(self, features, num_classes=10, init_weights=True, dropout=0.5):
        super().__init__()
        self.features = features
        self.avgpool = nn.AdaptiveAvgPool2d((1, 1))
        self.classifier = nn.Sequential(nn.Linear(32 * 1 * 1, 64), nn.ReLU(True), nn.Dropout(p=dropout), nn.Linear(64, 64), nn.ReLU(True), nn.Dropout(p=dropout), nn.Linear(64, num_classes))

    def forward(self, inp):
        inp = self.features(inp)
        inp = self.avgpool(inp)
        inp = torch.flatten(inp, 1)
        inp = self.classifier(inp)
        return inp
cfgs = {'A': [8, 'M', 16, 'M', 32, 'M', 32, 32, 'M'], 'B': [8, 8, 'M', 16, 'M', 32, 'M', 32, 32, 'M']}

def _plainnet(cfg, batch_norm, **kwargs):
    return PlainNet(make_layers(cfgs[cfg], batch_norm=batch_norm), **kwargs)

def plainnet_a(**kwargs):
    return _plainnet('B', False, **kwargs)
