class Block(nn.Module):

    def __init__(self, in_chs, inter_chs, out_chs, norm_layer, act_layer, device=None, dtype=None):
        dd = {'device': device, 'dtype': dtype}
        super().__init__()
        self.layers = nn.Sequential(nn.Conv2d(in_chs, in_chs, groups=in_chs, kernel_size=7, stride=1, padding=3, **dd), norm_layer(in_chs, **dd), nn.Conv2d(in_chs, inter_chs, kernel_size=1, stride=1, padding=0, **dd), act_layer(), nn.Conv2d(inter_chs, out_chs, kernel_size=1, stride=1, padding=0, **dd))

    def forward(self, x):
        return self.layers(x)

class BlockESE(nn.Module):

    def __init__(self, in_chs, inter_chs, out_chs, norm_layer, act_layer, device=None, dtype=None):
        dd = {'device': device, 'dtype': dtype}
        super().__init__()
        self.layers = nn.Sequential(nn.Conv2d(in_chs, in_chs, groups=in_chs, kernel_size=7, stride=1, padding=3, **dd), norm_layer(in_chs, **dd), nn.Conv2d(in_chs, inter_chs, kernel_size=1, stride=1, padding=0, **dd), act_layer(), nn.Conv2d(inter_chs, out_chs, kernel_size=1, stride=1, padding=0, **dd), EffectiveSEModule(out_chs, **dd))

    def forward(self, x):
        return self.layers(x)

def _get_block_type(block):
    block = block.lower().strip()
    if block == 'block':
        return Block
    elif block == 'blockese':
        return BlockESE
    else:
        assert False, f'Unknown block type ({block}).'

class DenseBlock(nn.Module):

    def __init__(self, num_input_features=64, growth_rate=64, bottleneck_width_ratio=4.0, drop_path_rate=0.0, drop_rate=0.0, rand_gather_step_prob=0.0, block_idx=0, block_type='Block', ls_init_value=1e-06, norm_layer=nn.LayerNorm, act_layer=nn.GELU, device=None, dtype=None):
        dd = {'device': device, 'dtype': dtype}
        super().__init__()
        self.drop_rate = drop_rate
        self.drop_path_rate = drop_path_rate
        self.rand_gather_step_prob = rand_gather_step_prob
        self.block_idx = block_idx
        self.growth_rate = growth_rate
        self.gamma = nn.Parameter(ls_init_value * torch.ones(growth_rate, **dd)) if ls_init_value > 0 else None
        growth_rate = int(growth_rate)
        inter_chs = int(num_input_features * bottleneck_width_ratio / 8) * 8
        self.drop_path = DropPath(drop_path_rate)
        self.layers = _get_block_type(block_type)(in_chs=num_input_features, inter_chs=inter_chs, out_chs=growth_rate, norm_layer=norm_layer, act_layer=act_layer, **dd)

    def forward(self, x):
        x = torch.cat(x, 1)
        x = self.layers(x)
        if self.gamma is not None:
            x = x.mul(self.gamma.reshape(1, -1, 1, 1))
        x = self.drop_path(x)
        if self.drop_rate > 0:
            x = F.dropout(x, p=self.drop_rate, training=self.training)
        return x

class DenseStage(nn.Sequential):

    def __init__(self, num_block, num_input_features, drop_path_rates, growth_rate, device=None, dtype=None, **kwargs):
        dd = {'device': device, 'dtype': dtype}
        super().__init__()
        for i in range(num_block):
            layer = DenseBlock(num_input_features=num_input_features, growth_rate=growth_rate, drop_path_rate=drop_path_rates[i], block_idx=i, **dd, **kwargs)
            num_input_features += growth_rate
            self.add_module(f'dense_block{i}', layer)
        self.num_out_features = num_input_features

    def forward(self, init_feature):
        features = [init_feature]
        for module in self:
            new_feature = module(features)
            features.append(new_feature)
        return torch.cat(features, 1)

class RDNet(nn.Module):

    def __init__(self, in_chans=3, num_classes=1000, global_pool='avg', growth_rates=(64, 104, 128, 128, 128, 128, 224), num_blocks_list=(3, 3, 3, 3, 3, 3, 3), block_type=('Block',) * 2 + ('BlockESE',) * 5, is_downsample_block=(None, True, True, False, False, False, True), bottleneck_width_ratio=4.0, transition_compression_ratio=0.5, ls_init_value=1e-06, stem_type='patch', patch_size=4, num_init_features=64, head_init_scale=1.0, head_norm_first=False, conv_bias=True, act_layer='gelu', norm_layer='layernorm2d', norm_eps=None, drop_rate=0.0, proj_drop_rate=0.0, drop_path_rate=0.0, device=None, dtype=None):
        super().__init__()
        dd = {'device': device, 'dtype': dtype}
        assert len(growth_rates) == len(num_blocks_list) == len(is_downsample_block)
        act_layer = get_act_layer(act_layer)
        norm_layer = get_norm_layer(norm_layer)
        if norm_eps is not None:
            norm_layer = partial(norm_layer, eps=norm_eps)
        self.num_classes = num_classes
        self.in_chans = in_chans
        self.drop_rate = drop_rate
        self.grad_checkpointing = False
        assert stem_type in ('patch', 'overlap', 'overlap_tiered')
        if stem_type == 'patch':
            self.stem = nn.Sequential(nn.Conv2d(in_chans, num_init_features, kernel_size=patch_size, stride=patch_size, bias=conv_bias, **dd), norm_layer(num_init_features, **dd))
            stem_stride = patch_size
        else:
            mid_chs = make_divisible(num_init_features // 2) if 'tiered' in stem_type else num_init_features
            self.stem = nn.Sequential(nn.Conv2d(in_chans, mid_chs, kernel_size=3, stride=2, padding=1, bias=conv_bias, **dd), nn.Conv2d(mid_chs, num_init_features, kernel_size=3, stride=2, padding=1, bias=conv_bias, **dd), norm_layer(num_init_features, **dd))
            stem_stride = 4
        self.feature_info = []
        self.num_stages = len(growth_rates)
        curr_stride = stem_stride
        num_features = num_init_features
        dp_rates = calculate_drop_path_rates(drop_path_rate, num_blocks_list, stagewise=True)
        dense_stages = []
        for i in range(self.num_stages):
            dense_stage_layers = []
            if i != 0:
                compressed_num_features = int(num_features * transition_compression_ratio / 8) * 8
                k_size = stride = 1
                if is_downsample_block[i]:
                    curr_stride *= 2
                    k_size = stride = 2
                dense_stage_layers.append(norm_layer(num_features, **dd))
                dense_stage_layers.append(nn.Conv2d(num_features, compressed_num_features, kernel_size=k_size, stride=stride, padding=0, **dd))
                num_features = compressed_num_features
            stage = DenseStage(num_block=num_blocks_list[i], num_input_features=num_features, growth_rate=growth_rates[i], bottleneck_width_ratio=bottleneck_width_ratio, drop_rate=proj_drop_rate, drop_path_rates=dp_rates[i], ls_init_value=ls_init_value, block_type=block_type[i], norm_layer=norm_layer, act_layer=act_layer, **dd)
            dense_stage_layers.append(stage)
            num_features += num_blocks_list[i] * growth_rates[i]
            if i + 1 == self.num_stages or (i + 1 != self.num_stages and is_downsample_block[i + 1]):
                self.feature_info += [dict(num_chs=num_features, reduction=curr_stride, module=f'dense_stages.{i}', growth_rate=growth_rates[i])]
            dense_stages.append(nn.Sequential(*dense_stage_layers))
        self.dense_stages = nn.Sequential(*dense_stages)
        self.stage_ends = [int(info['module'].split('.')[-1]) for info in self.feature_info]
        self.num_features = num_features
        if head_norm_first:
            self.norm_pre = norm_layer(self.num_features, **dd)
            self.head = ClassifierHead(self.num_features, num_classes, pool_type=global_pool, drop_rate=self.drop_rate, **dd)
        else:
            self.norm_pre = nn.Identity()
            self.head = NormMlpClassifierHead(self.num_features, num_classes, pool_type=global_pool, drop_rate=self.drop_rate, norm_layer=norm_layer, **dd)
        self.head_hidden_size = self.head.num_features

    def forward_features(self, x):
        x = self.stem(x)
        if self.grad_checkpointing and (not torch.jit.is_scripting()):
            x = checkpoint_seq(self.dense_stages, x)
        else:
            x = self.dense_stages(x)
        x = self.norm_pre(x)
        return x

    def forward_head(self, x, pre_logits=False):
        return self.head(x, pre_logits=True) if pre_logits else self.head(x)

    def forward(self, x):
        x = self.forward_features(x)
        x = self.forward_head(x)
        return x

def checkpoint_filter_fn(state_dict, model):
    if 'stem.0.weight' in state_dict:
        return state_dict
    if 'model' in state_dict:
        state_dict = state_dict['model']
    out_dict = {}
    for k, v in state_dict.items():
        k = k.replace('stem.stem.', 'stem.')
        out_dict[k] = v
    return out_dict

def _create_rdnet(variant, pretrained=False, **kwargs):
    model = build_model_with_cfg(RDNet, variant, pretrained, pretrained_filter_fn=checkpoint_filter_fn, feature_cfg=dict(out_indices=(0, 1, 2, 3), flatten_sequential=True), **kwargs)
    return model

@register_model
def rdnet_tiny(pretrained=False, **kwargs):
    n_layer = 7
    model_args = {'num_init_features': 64, 'growth_rates': [64] + [104] + [128] * 4 + [224], 'num_blocks_list': [3] * n_layer, 'is_downsample_block': (None, True, True, False, False, False, True), 'transition_compression_ratio': 0.5, 'block_type': ['Block'] + ['Block'] + ['BlockESE'] * 4 + ['BlockESE']}
    model = _create_rdnet('rdnet_tiny', pretrained=pretrained, **dict(model_args, **kwargs))
    return model
model = rdnet_tiny()
