from typing import Any, Callable, List, Optional
import torch
from torch import Tensor, nn
import torch.nn.functional as F
from functools import partial
from torch.utils.checkpoint import checkpoint_sequential

def _quantize(width, group_width):
    group_width = min(group_width, width)
    return int(round(width / group_width) * group_width)

class YBlock(nn.Module):

    def __init__(self, in_ch, out_ch, stride, group_width, bottleneck_ratio=1.0, se_ratio=None):
        super().__init__()
        w_b = int(round(out_ch * bottleneck_ratio))
        groups = w_b // group_width
        self.conv_a = nn.Sequential(nn.Conv2d(in_ch, w_b, 1, bias=False), nn.BatchNorm2d(w_b), nn.Hardswish())
        self.conv_b = nn.Sequential(nn.Conv2d(w_b, w_b, 3, stride=stride, padding=1, groups=groups, bias=False), nn.BatchNorm2d(w_b), nn.Hardswish())
        self.se = None
        self.conv_c = nn.Sequential(nn.Conv2d(w_b, out_ch, 1, bias=False), nn.BatchNorm2d(out_ch))
        self.proj = None
        if in_ch != out_ch or stride != 1:
            self.proj = nn.Sequential(nn.Conv2d(in_ch, out_ch, 1, stride=stride, bias=False), nn.BatchNorm2d(out_ch))
        self.act = nn.Hardswish()

    def forward(self, x):
        shortcut = x if self.proj is None else self.proj(x)
        x = self.conv_a(x)
        x = self.conv_b(x)
        if self.se is not None:
            x = self.se(x)
        x = self.conv_c(x)
        return self.act(x + shortcut)

class Fire(nn.Module):

    def __init__(self, inplanes, squeeze_planes, expand1x1_planes, expand3x3_planes):
        super().__init__()
        self.inplanes = inplanes
        self.sq = nn.Conv2d(inplanes, squeeze_planes, kernel_size=1)
        self.ex1 = nn.Conv2d(squeeze_planes, expand1x1_planes, kernel_size=1)
        self.ex3 = nn.Conv2d(squeeze_planes, expand3x3_planes, kernel_size=3, padding=1)
        self.squeeze_activation = nn.Hardswish()
        self.expand1x1_activation = nn.Hardswish()
        self.expand3x3_activation = nn.Hardswish()

    def forward(self, x):
        x = self.squeeze_activation(self.sq(x))
        return torch.cat([self.expand1x1_activation(self.ex1(x)), self.expand3x3_activation(self.ex3(x))], 1)

class ConvNormAct(nn.Module):

    def __init__(self, in_channels, out_channels, kernel_size=3, stride=1, groups=1, act=True):
        super().__init__()
        padding = (kernel_size - 1) // 2 if isinstance(kernel_size, int) else tuple(((k - 1) // 2 for k in kernel_size))
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size, stride=stride, padding=padding, groups=groups, bias=False)
        self.bn = nn.BatchNorm2d(out_channels)
        self.use_act = act
        self.act = nn.Hardswish()

    def forward(self, x):
        x = self.conv(x)
        x = self.bn(x)
        if self.use_act:
            x = self.act(x)
        return x

class TinyNet(nn.Module):

    def __init__(self, conv_cfg, block_cfg, in_chans=3, num_classes=100, drop_rate=0.0, norm_layer=None, **kwargs):
        super().__init__()
        if norm_layer is None:
            norm_layer = partial(nn.BatchNorm2d, eps=0.001)
        self.num_classes = num_classes
        self.stem = ConvNormAct(in_chans, 8, kernel_size=3, stride=2)
        in_ch = 8
        blocks = []
        for idx, (w, d, g) in enumerate(conv_cfg):
            w = _quantize(w, g)
            for i in range(d):
                blocks.append(YBlock(in_ch, w, 2 if i == 0 else 1, g))
                in_ch = w
        for idx, (sq, e, n) in enumerate(block_cfg, start=len(conv_cfg)):
            if idx > 0:
                blocks.append(nn.MaxPool2d(kernel_size=3, stride=2, ceil_mode=True))
            for _ in range(n):
                blocks.append(Fire(in_ch, sq, e, e))
                in_ch = 2 * e
        self.features = nn.Sequential(*blocks)
        self.grad_checkpointing = False
        self.drop = nn.Identity()
        self.fc = nn.Linear(in_ch, num_classes)

    def forward_features(self, x):
        x = self.stem(x)
        if self.grad_checkpointing and (not torch.jit.is_scripting()):
            x = checkpoint_sequential(self.features, len(self.features), x)
        else:
            x = self.features(x)
        return x

    def forward_head(self, x, pre_logits=False):
        x = F.adaptive_avg_pool2d(x, 1)
        x = x.flatten(1)
        x = self.drop(x)
        return x if pre_logits else self.fc(x)

    def forward(self, x):
        x = self.forward_features(x)
        x = self.forward_head(x)
        return x

def _tinynet(variant, weights=None, progress=True, **kwargs):
    cfgs = {'small': ([(24, 2, 8), (40, 1, 16), (56, 1, 16)], [(32, 128, 1), (40, 160, 1)]), 'base': ([(24, 2, 8), (40, 1, 16), (56, 1, 16)], [(32, 128, 2), (40, 160, 2)])}
    model = TinyNet(*cfgs[variant], **kwargs)
    if weights is not None:
        model.load_state_dict(weights.get_state_dict(progress=progress))
    return model

def make_model(weights=None, progress=True, **kwargs):
    return _tinynet('base', weights, progress, **kwargs)
model = make_model(num_classes=10)
example_input = torch.randn(1, 3, 64, 64)
