class IFormer(nn.Module):

    def __init__(self, in_chans=3, num_classes=1000, global_pool='avg', dims=(32, 64, 128, 256), depths=(2, 2, 16, 6), attn_groups=(0, 0, 3, 2), attn_head_dim_reduction=(0, 0, 2, 4), conv_ratio=3, ffn_ratio=2, attn_ratio=1, drop_rate=0.0, drop_path_rate=0.0, layer_scale_init_value=0.0, act_layer=nn.GELU, distillation=False, device=None, dtype=None):
        super().__init__()
        dd = {'device': device, 'dtype': dtype}
        self.num_classes = num_classes
        self.in_chans = in_chans
        assert global_pool in ('', 'avg'), 'Only avg pooling (or none) is supported.'
        self.global_pool = global_pool
        self.distillation = distillation
        assert len(dims) == len(depths) == len(attn_groups) == len(attn_head_dim_reduction)
        self.num_stages = len(depths)
        self.feature_info = []
        self.stem = Stem(in_chans, dims[0], act_layer, **dd)
        prev_dim = dims[0]
        dpr = calculate_drop_path_rates(drop_path_rate, depths, stagewise=True)
        stages = []
        for i in range(self.num_stages):
            stage = StageBlock(in_dim=prev_dim, dim=dims[i], depth=depths[i], num_attn=attn_groups[i], hdrr=attn_head_dim_reduction[i], conv_ratio=conv_ratio, ffn_ratio=ffn_ratio, attn_ratio=attn_ratio, drop_path_rates=dpr[i], layer_scale_init_value=layer_scale_init_value, act_layer=act_layer, **dd)
            prev_dim = dims[i]
            stages.append(stage)
            self.feature_info += [dict(num_chs=dims[i], reduction=2 ** (i + 2), module=f'stages.{i}')]
        self.stages = nn.Sequential(*stages)
        self.num_features = self.head_hidden_size = dims[-1]
        self.head_drop = nn.Dropout(drop_rate)
        self.head = RepVitClassifier(dims[-1], num_classes, distillation, 0.0, **dd)

    def forward_features(self, x):
        x = self.stem(x)
        x = self.stages(x)
        return x

    def forward_head(self, x, pre_logits=False):
        if self.global_pool == 'avg':
            x = x.mean((2, 3), keepdim=False)
        x = self.head_drop(x)
        if pre_logits:
            return x
        return self.head(x)

    def forward(self, x):
        x = self.forward_features(x)
        x = self.forward_head(x)
        return x

    @torch.no_grad()
    def fuse(self):

        def fuse_children(net):
            for child_name, child in net.named_children():
                if hasattr(child, 'fuse'):
                    fused = child.fuse()
                    if fused is not child:
                        setattr(net, child_name, fused)
                        fuse_children(fused)
                    else:
                        fuse_children(child)
                else:
                    fuse_children(child)
        fuse_children(self)
        return self

def checkpoint_filter_fn(state_dict, model):
    if 'model' in state_dict and isinstance(state_dict['model'], dict):
        state_dict = state_dict['model']
    if 'state_dict' in state_dict and isinstance(state_dict['state_dict'], dict):
        state_dict = state_dict['state_dict']
    out_dict = {}
    for key, value in state_dict.items():
        if key.startswith('classifier.classifier_dist.'):
            key = key.replace('classifier.classifier_dist.', 'head.head_dist.', 1)
        elif key.startswith('classifier.classifier.'):
            key = key.replace('classifier.classifier.', 'head.head.', 1)
        elif key.startswith('classifier.'):
            key = key.replace('classifier.', 'head.head.', 1)
        if key.startswith('downsample_layers.0.0.'):
            key = key.replace('downsample_layers.0.0.', 'stem.conv1.', 1)
        elif key.startswith('downsample_layers.0.2.conv_exp_bn1.'):
            key = key.replace('downsample_layers.0.2.conv_exp_bn1.', 'stem.conv2.', 1)
        elif key.startswith('downsample_layers.0.2.conv_pwl_bn2.'):
            key = key.replace('downsample_layers.0.2.conv_pwl_bn2.', 'stem.conv3.', 1)
        elif key.startswith('downsample_layers.'):
            m = re.match('^downsample_layers\\.(\\d+)\\.0\\.(.*)', key)
            if m:
                key = f'stages.{m.group(1)}.downsample.{m.group(2)}'
            else:
                m = re.match('^downsample_layers\\.(\\d+)\\.(.*)', key)
                if m:
                    key = f'stages.{m.group(1)}.downsample.{m.group(2)}'
            key = key.replace('token_channel_mixer', 'mixer')
            key = key.replace('channel_mixer', 'mixer')
            key = key.replace('.m.', '.module.')
            out_dict[key] = value
            continue
        m = re.match('^stages\\.(\\d+)\\.(\\d+)\\.block\\.(.*)', key)
        if m:
            si, bi, rest = (int(m.group(1)), int(m.group(2)), m.group(3))
            key = f'stages.{si}.blocks.{bi}.{rest}'
        elif key.startswith('stages.'):
            m = re.match('^stages\\.(\\d+)\\.(\\d+)\\.(.*)', key)
            if m:
                si, bi, rest = (int(m.group(1)), int(m.group(2)), m.group(3))
                key = f'stages.{si}.blocks.{bi}.{rest}'
        key = key.replace('token_channel_mixer', 'mixer')
        key = key.replace('channel_mixer', 'mixer')
        key = key.replace('.m.', '.module.')
        out_dict[key] = value
    return out_dict

def _create_iformer(variant, pretrained=False, **kwargs):
    load_context = nullcontext()
    if pretrained and hasattr(torch.serialization, 'safe_globals'):
        numpy_core = np._core if hasattr(np, '_core') else np.core
        scalar = numpy_core.multiarray.scalar
        safe_types = [argparse.Namespace, np.dtype, type(np.dtype('float64'))]
        if np.lib.NumpyVersion(np.__version__) >= '2.0.0':
            safe_types.append((scalar, 'numpy.core.multiarray.scalar'))
        else:
            safe_types.append(scalar)
        load_context = torch.serialization.safe_globals(safe_types)
