class RepCPE(nn.Module):

    def __init__(self, dim, kernel_size=7, device=None, dtype=None):
        dd = {'device': device, 'dtype': dtype}
        super().__init__()
        self.cpe = Residual(ConvNorm(dim, dim, kernel_size, 1, kernel_size // 2, groups=dim, **dd), **dd)

    @torch.no_grad()
    def fuse(self):
        conv = self.cpe.module.fuse()
        kh, kw = conv.kernel_size
        conv.weight[:, :, kh // 2, kw // 2] += 1
        return conv

    def forward(self, x):
        return self.cpe(x)
